insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ لِأَهْلِ الْجَاهِلِيَّةِ يَوْمَانِ فِي كُلِّ سَنَةٍ يَلْعَبُونَ فِيهِمَا، فَلَمَّا قَدِمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ قَالَ: "كَانَ لَكُمْ يَوْمَانِ تَلْعَبُونَ فِيهِمَا، وَقَدْ أَبْدَلَكُمُ اللهُ بِهِمَا خَيْرًا مِنْهُمَا: يَوْمَ الْفِطْرِ وَيَوْمَ الْأَضْحَى". (ن)', 'അനസുബ്നു മാലിക്(റ): എല്ലാ വർഷവും വിനോദത്തിൽ ഏർപ്പെടുന്ന രണ്ടു ദിവസങ്ങൾ ജാഹിലിയ്യാ കാലത്തെ ആളുകൾക്കുണ്ടായിരുന്നു. നബി(സ) മദീനയിൽ വന്നപ്പോൾ പറഞ്ഞു: "വിനോദത്തിൽ ഏർപ്പെടാൻ രണ്ടു ദിവസങ്ങൾ നിങ്ങൾക്കുണ്ടായിരുന്നു. അല്ലാഹു നിങ്ങൾക്ക് അതിലും ഉത്തമമായ രണ്ടു ദിവസങ്ങൾ നൽകിയിരിക്കുന്നു. അവ ചെറിയ പെരുന്നാളും, ബലി പെരുന്നാളുമാണ്." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، وَلَهُمْ يَوْمَانِ يَلْعَبُونَ فِيهِمَا فَقَالَ: "مَا هَذَانِ الْيَوْمَانِ؟" قَالُوا: كُنَّا نَلْعَبُ فِيهِمَا فِي الْجَاهِلِيَّةِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ قَدْ أَبْدَلَكُمْ بِهِمَا خَيْرًا مِنْهُمَا، يَوْمَ الْأَضْحَى وَيَوْمَ الْفِطْرِ". (د,ت,ن)', 'അനസ്(റ): നബി(സ) മദീനയിൽ വരുമ്പോൾ അവർ രണ്ടു ദിവസം ആഘോഷമായി കൊണ്ടാടിയിരുന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "എന്ത് ദിവസങ്ങളാണിത്?" അവർ പറഞ്ഞു: ജാഹിലിയ്യാ കാലത്തെ ഞങ്ങളുടെ ആഘോഷമാണിത്. നബി(സ) പറഞ്ഞു: "അല്ലാഹു നിങ്ങൾക്ക് ആ രണ്ട് ദിവസങ്ങളേക്കാൾ ഉത്തമമായ രണ്ടു ദിവസങ്ങളായി ചെറിയ പെരുന്നാളിനെയും, ബലി പെരുന്നാളിനെയും പകരമാക്കിയിരിക്കുന്നു." (ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَغْدُو يَوْمَ الْفِطْرِ حَتَّى يَأْكُلَ تَمَرَاتٍ، وَفِي رِوَايَةٍ عَنْهُ قَالَ: وَيَأْكُلُهُنَّ وِتْرًا. (خ,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) കുറച്ച് ഈത്തപ്പഴം തിന്നിട്ടല്ലാതെ ചെറിയ പെരുന്നാൾ ദിവസം പുറത്തു പോകാറില്ലായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) അവ തിന്നിരുന്നത് ഒറ്റയിൽ അവസാനിക്കുന്ന ക്രമത്തിലായിരുന്നു. (ബു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=3), 1, 'وَفِي رِوَايَةٍ عَنْهُ قَالَ: وَيَأْكُلُهُنَّ وِتْرًا. (خ,جه)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) അവ തിന്നിരുന്നത് ഒറ്റയിൽ അവസാനിക്കുന്ന ക്രമത്തിലായിരുന്നു. (ബു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَغْدُو يَوْمَ الْفِطْرِ حَتَّى يُغَذِّيَ أَصْحَابَهُ مِنْ صَدَقَةِ الْفِطْرِ. [ز: في إسناده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): ഫിത്വർ സക്കാത്തിൽ നിന്ന് (പെരുന്നാൾ ദിവസം സാധുക്കൾക്ക് വിതരണം ചെയ്യേണ്ട ധർമ്മം) തന്റെ അനുയായികൾക്ക് ആഹാരം നൽകാതെ നബി(സ) പെരുന്നാൾ ദിവസം (ചെറിയ പെരുന്നാൾ ദിവസം) പുറത്തു പോകാറില്ലായിരുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَخْرُجُ يَوْمَ الْفِطْرِ حَتَّى يَأْكُلَ، وَكَانَ لَا يَأْكُلُ يَوْمَ النَّحْرِ حَتَّى يَرْجِعَ. (ت,جه)', 'ബുറൈദ(റ): ചെറിയ പെരുന്നാൾ ദിവസം എന്തെങ്കിലും കഴിക്കാതെ നബി(സ) പുറത്തു പോകാറില്ലായിരുന്നു. ബലി പെരുന്നാൾ ദിവസം, നിസ്കാരം കഴിഞ്ഞു മടങ്ങുംവരെ യാതൊന്നും ഭക്ഷിക്കാറുമില്ലായിരുന്നു. (തു,ജ)', 'ابْنِ بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 664, 664, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فَقَالَ: "إِنَّ أَوَّلَ مَا نَبْدَأُ بِهِ فِي يَوْمِنَا هَذَا أَنْ نُصَلِّيَ ثُمَّ نَرْجِعَ فَنَنْحَرَ، فَمَنْ فَعَلَ فَقَدْ أَصَابَ سُنَّتَنَا". (خ)', 'ബറാഉബ്നു ആസിബ്(റ): നബി(സ) പ്രസംഗിക്കുന്നതു ഞാൻ കേട്ടു. നബി(സ) പറഞ്ഞു: "ഈ ദിവസം (ബലി പെരുന്നാൾ ദിവസം) നാം ആദ്യം ചെയ്യേണ്ടത് നിസ്കാരവും പിന്നീട് മടങ്ങി വന്നശേഷം ബലിയറുക്കലുമാണ്. ആർ ഈ പ്രവൃത്തികൾ ചെയ്യുന്നുവോ, അവൻ നമ്മുടെ ചര്യ അനുഷ്ഠിച്ചു." (ബു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 664, 664, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْأَضْحَى بَعْدَ الصَّلَاةِ فَقَالَ: "مَنْ صَلَّى صَلَاتَنَا، وَنَسَكَ نُسْكَنَا، فَقَدْ أَصَابَ النُّسْكَ، وَمَنْ نَسَكَ قَبْلَ الصَّلَاةِ، فَإِنَّهُ قَبْلَ الصَّلَاةِ وَلَا نُسْكَ لَهُ". فَقَالَ أَبُو بُرْدَةَ بْنُ نِيَارٍ خَالُ الْبَرَاءِ: يَا رَسُولَ اللهِ، فَإِنِّي نَسَكْتُ شَاتِي قَبْلَ الصَّلَاةِ، وَعَرَفْتُ أَنَّ الْيَوْمَ يَوْمُ أَكْلٍ وَشُرْبٍ، وَأَحْبَبْتُ أَنْ تَكُونَ شَاتِي أَوَّلَ مَا يُذْبَحُ فِي بَيْتِي، فَذَبَحْتُ شَاتِي وَتَغَدَّيْتُ قَبْلَ أَنْ آتِيَ الصَّلَاةَ. فَقَالَ: "شَاتُكَ شَاةُ لَحْمٍ." فَقَالَ: يَا رَسُولَ اللهِ، فَإِنَّ عِنْدَنَا عَنَاقًا لَنَا جَذَعَةً هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْنِ، أَفَتَجْزِي عَنِّي؟ قَالَ: "نَعَمْ، وَلَنْ تَجْزِيَ عَنْ أَحَدٍ بَعْدَكَ". (خ,ن)', 'ബറാഉബ്നു ആസിബ്(റ): ബലി പെരുന്നാൾ ദിവസം നിസ്കാര ശേഷം നബി(സ) തന്റെ പ്രസംഗത്തിൽ പറഞ്ഞു: "ഒരാൾ നാം നിസ്കരിക്കുന്നതുപോലെ നിസ്കരിക്കുകയും, നാം ബലിയറക്കുന്നതുപോലെ അറുക്കുകയും ചെയ്താൽ അവൻ ബലി അനുഷ്ഠിച്ചവനായിത്തീർന്നു. ആർ, നിസ്കാരത്തിന് മുമ്പ് ബലി കർമ്മം അനുഷ്ഠിക്കുന്നുവോ, അവൻ നിസ്കാരത്തിനു മുമ്പ് കർമ്മം ചെയ്യുന്നുവെന്നേയുള്ളൂ. പക്ഷേ, യഥാർത്ഥ ബലി അനുഷ്ഠിച്ചത് (പ്രതിഫലം) അവനു ലഭിക്കുകയില്ല." ബറാഇന്റെ അമ്മാവനായ അബൂബുർദതുബ്നു നിയാർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ, നിസ്കരിക്കുന്നതിനുമുമ്പ് ഞാൻ എന്റെ ഒരു ആടിനെ ബലി അറുത്തുവല്ലോ. ഈ ദിവസം (ഇഷ്ടപ്പെട്ടത്) തിന്നുകയും കുടിക്കുകയും ചെയ്യേണ്ട ദിവസമാണെന്നെനിക്കറിയാമായിരുന്നു. എന്റെ വീട്ടിൽ അറുക്കുന്ന ആദ്യത്തെ ആട് എന്റെ ആടാവട്ടെ എന്ന് ഞാൻ ആഗ്രഹിച്ചുപോയി. അതുകൊണ്ട് ഞാൻ എന്റെ ആടിനെ അറുക്കുകയും നിസ്കാരത്തിന് പോകും മുമ്പ് (പാകം ചെയ്തു) കഴിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളുടെ ആടിന് ഇറച്ചി മാത്രമേയുള്ളൂ." അദ്ദേഹം പറഞ്ഞു: പ്രവാചകരെ, ഞങ്ങളുടെയടുക്കൽ ഒരു ചെറിയ പെണ്ണാടുണ്ട്. അത് രണ്ടു മുട്ടനാടുകളേക്കാൾ എനിക്ക് ഇഷ്ടപ്പെട്ടതുമാണ്. അതിനെ അറുത്താൽ മതിയാകുമോ? നബി(സ) അരുളി: "അതേ, മതിയാകുന്നതാണ്. എന്നാൽ ഇത് നിങ്ങൾക്കു ശേഷം മറ്റാർക്കും മതിയാവുന്നതല്ല¹." (ബു,ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', '¹. ഉള്ഹിയ്യത്തിന് നിശ്ചിത പ്രായം തികഞ്ഞ ആട് വേണം. പ്രായം കുറഞ്ഞത് മതിയാവില്ല. ഇത് ഇദ്ദേഹത്തിനു (അബൂ ബുർദക്കു) മാത്രമായി ലഭിച്ച ആനുകൂല്യമാണ്.', null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 664, 664, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: وَجَدَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ حُلَّةً مِنْ إِسْتَبْرَقٍ بِالسُّوقِ، فَأَخَذَهَا فَأَتَى بِهَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، ابْتَعْ هَذِهِ، فَتَجَمَّلْ بِهَا لِلْعِيدِ وَالْوَفْدِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا هَذِهِ لِبَاسُ مَنْ لَا خَلَاقَ لَهُ". أَوْ: "إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لَا خَلَاقَ لَهُ". فَلَبِثَ عُمَرُ مَا شَاءَ اللهُ، ثُمَّ أَرْسَلَ إِلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِجُبَّةِ دِيبَاجٍ، فَأَقْبَلَ بِهَا حَتَّى جَاءَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، قُلْتَ: إِنَّمَا هَذِهِ لِبَاسُ مَنْ لَا خَلَاقَ لَهُ. ثُمَّ أَرْسَلْتَ إِلَيَّ بِهَذِهِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بِعْهَا، وَتُصِبْ بِهَا حَاجَتَكَ". (ن)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ) ചന്തയിൽ ഒരു പട്ടുവസ്ത്രം കണ്ടു. അദ്ദേഹം അതു വാങ്ങി നബി(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലെ, ഇത് വാങ്ങിയാലും, അങ്ങേയ്ക്ക് ഇത് പെരുന്നാളിനും, നിവേദക സംഘം വരുമ്പോഴും ധരിക്കാമല്ലോ. തിരുമേനി(സ) പ്രതിവചിച്ചു: "ഇത് (പരലോകത്ത്) ഓഹരി ഇല്ലാത്തവരുടെ വസ്ത്രമാണ്. അല്ലെങ്കിൽ പരലോകത്ത് ഭാഗ്യം ലഭിക്കാത്തവരാണ് ഇത് ധരിക്കുന്നത്." കുറേക്കാലം കഴിഞ്ഞു. പിന്നീടൊരിക്കൽ നബി(സ) ഒരു പട്ടുടുപ്പ് ഉമറി(റ)ന് അയച്ചുകൊടുത്തു. അതുമായി ഉമർ(റ) നബി(സ)യുടെ അടുത്ത് വന്നുകൊണ്ട് പറഞ്ഞു: നബിയേ! ഇത് ഹതഭാഗ്യരുടെ വസ്ത്രമാണെന്ന് അങ് പറഞ്ഞിരുന്നുവല്ലോ? പിന്നെ അവിടുന്ന് ഇതെനിക്ക് കൊടുത്തയക്കുകയും ചെയ്തുവല്ലോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "താങ്കൾ ഇതു വിറ്റ് താങ്കളുടെ ആവശ്യങ്ങൾ നിറവേറ്റുക." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْدُو إِلَى الْمُصَلَّى فِي يَوْمِ الْعِيدِ، وَالْعَنَزَةُ تُحْمَلُ بَيْنَ يَدَيْهِ. فَإِذَا بَلَغَ الْمُصَلَّى نُصِبَتْ بَيْنَ يَدَيْهِ، فَيُصَلِّي إِلَيْهَا. وَذَلِكَ أَنَّ الْمُصَلَّى كَانَ فَضَاءً، لَيْسَ فِيهِ شَيْءٌ يُسْتَتَرُ بِهِ. (خ,جه)', 'ഇബ്നുഉമർ(റ): കുന്തമുനയുള്ള വടിയു മുന്നിൽ ചുമന്നുകൊണ്ട് നബി(സ) പ്രഭാതത്തിൽ പെരുന്നാൾ ദിവസം നിസ്കാര സ്ഥലത്തേക്കു പോകും. നിസ്കാര സ്ഥലത്തെത്തിയാൽ ആ വടി തന്റെ മുന്നിൽ നാട്ടുകയും, അതിലേക്കു തിരിഞ്ഞ് നിസ്കരിക്കുകയും ചെയ്യും. നിസ്കാര സ്ഥലം തുറസ്സായതിനാലും ഒന്നും മറയായിട്ട് ഇല്ലാത്തതിനാലും ആയിരുന്നു ഇത്. (ബു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى يَوْمَ عِيدٍ أَوْ غَيْرِهِ، نُصِبَتِ الْحَرْبَةُ بَيْنَ يَدَيْهِ فَيُصَلِّي إِلَيْهَا. وَالنَّاسُ مِنْ خَلْفِهِ، قَالَ نَافِعٌ: فَمِنْ ثَمَّ اتَّخَذَهَا الْأُمَرَاءُ. (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പെരുന്നാൾ ദിവസമോ, അല്ലാത്ത ദിവസമോ നിസ്കരിക്കുകയാണെങ്കിൽ തന്റെ മുമ്പിൽ ഒരു കുന്തം നാട്ടി അതിലേക്കു തിരിഞ്ഞ് നിസ്കരിക്കും. പിന്നിൽ ജനങ്ങൾ നിസ്കരിക്കുന്നുണ്ടാവും. നാഫിഅ് പറഞ്ഞു: ഇവിടെ നിന്നാണ് ഭരണാധികാരികൾ ഈ ശൈലി സ്വീകരിച്ചത്. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْرُجُ يَوْمَ الْفِطْرِ وَالْأَضْحَى إِلَى الْمُصَلَّى، فَأَوَّلُ شَيْءٍ يَبْدَأُ بِهِ الصَّلَاةُ، ثُمَّ يَنْصَرِفُ، فَيَقُومُ مُقَابِلَ النَّاسِ وَالنَّاسُ جُلُوسٌ عَلَى صُفُوفِهِمْ، فَيَعِظُهُمْ وَيُوصِيهِمْ وَيَأْمُرُهُمْ، فَإِنْ كَانَ يُرِيدُ أَنْ يَقْطَعَ بَعْثًا قَطَعَهُ، أَوْ يَأْمُرَ بِشَيْءٍ أَمَرَ بِهِ، ثُمَّ يَنْصَرِفُ، قَالَ أَبُو سَعِيدٍ: فَلَمْ يَزَلِ النَّاسُ عَلَى ذَلِكَ حَتَّى خَرَجْتُ مَعَ مَرْوَانَ، وَهُوَ أَمِيرُ الْمَدِينَةِ فِي أَضْحَى أَوْ فِطْرٍ، فَلَمَّا أَتَيْنَا الْمُصَلَّى إِذَا مِنْبَرٌ بَنَاهُ كَثِيرُ بْنُ الصَّلْتِ، فَإِذَا مَرْوَانُ يُرِيدُ أَنْ يَرْتَقِيَهُ قَبْلَ أَنْ يُصَلِّيَ، فَجَبَذْتُ بِثَوْبِهِ، فَجَبَذَنِي فَارْتَفَعَ، فَخَطَبَ قَبْلَ الصَّلَاةِ، فَقُلْتُ لَهُ: غَيَّرْتُمْ وَاللهِ، فَقَالَ: أَبَا سَعِيدٍ، قَدْ ذَهَبَ مَا تَعْلَمُ، فَقُلْتُ: مَا أَعْلَمُ وَاللهِ خَيْرٌ مِمَّا لَا أَعْلَمُ، فَقَالَ: إِنَّ النَّاسَ لَمْ يَكُونُوا يَجْلِسُونَ لَنَا بَعْدَ الصَّلَاةِ، فَجَعَلْتُهَا قَبْلَ الصَّلَاةِ. (خ,ن)', 'അബൂസഈദുൽ ഖുദ്രി(റ): നബി(സ) ചെറിയ പെരുന്നാൾ ദിവസവും, ബലിപെരുന്നാൾ ദിവസവും നിസ്കാരത്തിനായി മുസ്വല്ല(നിസ്കാരസ്ഥലം)യിലേക്ക് പോകും. ആദ്യം നിസ്കാരം നിർവ്വഹിക്കും, പിന്നെ ആളുകളെ അഭിമുഖീകരിച്ച് നിൽക്കും. എല്ലാവരും അവരവരുടെ സ്വഫ്ഫുകളിൽ ഇരിക്കുന്നുണ്ടാകും. തുടർന്ന് നബി(സ) അവരെ ഉപദേശിക്കും. അവരോട് ചില കാര്യങ്ങൾ കൽപിക്കുകയും, വസ്വിയ്യത്ത് ചെയ്യുകയും ചെയ്യും. യുദ്ധത്തിനായി പട്ടാളത്തെ അയക്കാൻ ഉദ്ദേശിച്ചാൽ അങ്ങനെ ചെയ്യും. എന്തെങ്കിലും കൽപിക്കാൻ ഉദ്ദേശിച്ചാൽ അത് കൽപിച്ച ശേഷം നബി(സ) പ്രസംഗത്തിൽ നിന്ന് വിരമിക്കും. അബൂസഈദ് പറഞ്ഞു. (പിൽക്കാലത്തും) ജനങ്ങളുടെ സമ്പ്രദായം ഇപ്രകാരമായിരുന്നു. മർവാൻ മദീനയിലെ അമീർ ആയിരിക്കെ ഒരു പെരുന്നാൾ ദിവസം (ചെറിയ പെരുന്നാൾ ദിവസമോ അതോ ബലിപെരുന്നാൾ ദിവസമോ) ഞാൻ അദ്ദേഹത്തോടൊപ്പം നിസ്കരിക്കാൻ മുസ്വല്ലയിലേക്ക് പുറപ്പെട്ടു. ഞങ്ങൾ മുസ്വല്ലയിൽ എത്തിയപ്പോൾ, കസീറുബ്നു സ്വൽത് എന്നയാൾ നിർമ്മിച്ച ഒരു മിമ്പർ അവിടെ കണ്ടു. നിസ്കാരം നിർവ്വഹിക്കുന്നതിനു മുമ്പ് മർവാൻ മിമ്പറിൽ കയറാൻ (പ്രസംഗിക്കാൻ) ഒരുങ്ങി. അപ്പോൾ ഞാൻ അദ്ദേഹത്തിന്റെ വസ്ത്രം പിടിച്ചുവലിച്ചു. അദ്ദേഹം എന്നെ തള്ളിമാറ്റി മിമ്പറിൽ കയറി നിസ്കാരത്തിനു മുമ്പ് പ്രസംഗിച്ചു. അപ്പോൾ ഞാൻ അദ്ദേഹത്തോടു പറഞ്ഞു: അല്ലാഹുവാണെ, (നമ്മുടെ സമ്പ്രദായങ്ങൾ) നിങ്ങൾ മാറ്റിമറിച്ചിരിക്കുന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അബൂസഈദേ! നിങ്ങൾക്ക് അറിയാവുന്നതല്ലാം കഴിഞ്ഞുപോയിരുക്കുന്നു (മാറിപ്പോയിരിക്കുന്നു). ഞാൻ പറഞ്ഞു: എനിക്കറിയാവുന്നതാണ് അറിയാത്തതിനെക്കാൾ നല്ലത്. അദ്ദേഹം പറഞ്ഞു: നിസ്കാരം കഴിഞ്ഞാൽ ആളുകൾ (പ്രസംഗം) കേൾക്കാനിരിക്കുകയില്ല. അതുകൊണ്ടാണ് ഞാൻ നിസ്കാരത്തിനു മുമ്പ് പ്രസംഗിച്ചത്.² (ബു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', '². പെരുന്നാൾ നിസ്കാരത്തിനു ശേഷമാണ് ഖുത്വുബ നിർവ്വഹിക്കേണ്ടത്.', null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 665, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَبِي عُمَيْرِ بْنِ أَنَسِ بْنِ مَالِكٍ، عَنْ عُمُومَةٍ لَهُ: أَنَّ قَوْمًا رَأَوُا الْهِلَالَ، فَأَتَوُا النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهُمْ أَنْ يُفْطِرُوا بَعْدَ مَا ارْتَفَعَ النَّهَارُ، وَأَنْ يَخْرُجُوا إِلَى الْعِيدِ مِنَ الْغَدِ. (ن)', 'അബൂഉമൈർ ഇബ്നുഅനസ്ബ്നു മാലിക്(റ) തന്റെ പിതൃവ്യന്മാരിൽ നിന്ന്: ചില ആളുകൾ മാസപ്പിറവി കണ്ടു. അവർ നബി(സ)യുടെ അടുത്തെത്തി വിവരം അറിയിച്ചു. നേരം വെളുത്ത ശേഷം അവരോട് നോമ്പു മുറിക്കാനും അടുത്ത ദിവസം പെരുന്നാൾ നിസ്കാരത്തിന് എത്താനും നബി(സ) കൽപിച്ചു. (ന)', 'أَبِي عُمَيْرِ بْنِ أَنَسِ بْنِ مَالِكٍ، عَنْ عُمُومَةٍ لَهُ', 'അബൂഉമൈർ ഇബ്നുഅനസ്ബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 666, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُخْرِجُ الْعَنَزَةَ يَوْمَ الْفِطْرِ وَيَوْمَ الْأَضْحَى، يُرْكِزُهَا فَيُصَلِّي إِلَيْهَا. (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) ചെറിയ പെരുന്നാളിനും, ബലിപെരുന്നാളിനും നിസ്കാരത്തിനായി പുറപ്പെടുമ്പോൾ ഒരു വടി എടുക്കാറുണ്ടായിരുന്നു. അത് മുമ്പിലായി നിലത്തുറപ്പിച്ചു നിർത്തുകയും അതിലേക്ക് തിരിഞ്ഞ് നിസ്കരിക്കുകയും ചെയ്തിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 666, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نُخْرِجَهُنَّ فِي الْفِطْرِ وَالْأَضْحَى: الْعَوَاتِقَ وَالْحُيَّضَ وَذَوَاتِ الْخُدُورِ، فَأَمَّا الْحُيَّضُ فَيَعْتَزِلْنَ الصَّلَاةَ، وَيَشْهَدْنَ الْخَيْرَ وَدَعْوَةَ الْمُسْلِمِينَ. قُلْتُ: يَا رَسُولَ اللهِ، إِحْدَانَا لَا يَكُونُ لَهَا جِلْبَابٌ؟ قَالَ: "لِتُلْبِسْهَا أُخْتُهَا مِنْ جِلْبَابِهَا". (م)', 'ഉമ്മുഅത്വിയ്യ(റ): ചെറിയ പെരുന്നാളിനും, ബലിപെരുന്നാളിനും മുസ്വല്ലയിലേക്ക് സ്ത്രീകളെ കൊണ്ടുപോകാൻ നബി(സ) ഞങ്ങളോട് കൽപിച്ചു. കന്യകമാരേയും, അന്തപുരത്തിൽ കഴിഞ്ഞുകൂടുന്നവരേയും (മറയിൽ കഴിയുന്നവർ), ആർത്തവകാരികളെയും. ആർത്തവമുള്ളവർ നിസ്കാരത്തിൽ നിന്ന് മാറിനിൽക്കണം. നന്മ ചെയ്യുന്നതിലും മുസ്ലിംകളുടെ പ്രാർത്ഥനകളിലും പങ്കെടുക്കണം. ഞാൻ നബി(സ)യോടു ചോദിച്ചു: മൂടുപടം ഇല്ലാത്ത സ്ത്രീകളോ? നബി(സ) പറഞ്ഞു: "തന്റെ സഹോദരി അവളുടെ മൂടുപടം ഇല്ലാത്തവൾക്കു നൽകട്ടെ." (മു)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅത്വിയ്യ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 666, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ أَنْ نُخْرِجَ ذَوَاتِ الْخُدُورِ يَوْمَ الْعِيدِ. قِيلَ: فَالْحُيَّضُ؟ قَالَ: "لِيَشْهَدْنَ الْخَيْرَ، وَدَعْوَةَ الْمُسْلِمِينَ". قَالَ: فَقَالَتِ امْرَأَةٌ: يَا رَسُولَ اللهِ، إِنْ لَمْ يَكُنْ لِإِحْدَاهُنَّ ثَوْبٌ كَيْفَ تَصْنَعُ؟ قَالَ: "تُلْبِسُهَا صَاحِبَتُهَا طَائِفَةً مِنْ ثَوْبِهَا". وَفِي رِوَايَةٍ: قَالَ: "وَيَعْتَزِلُ الْحُيَّضُ مُصَلَّى الْمُسْلِمِينَ". وَلَمْ يَذْكُرِ الثَّوْبَ. وَفِي رِوَايَةٍ: قَالَتْ: كُنَّا نُؤْمَرُ بِهَذَا الْخَبَرِ. قَالَتْ: وَالْحُيَّضُ يَكُنَّ خَلْفَ النَّاسِ، فَيُكَبِّرْنَ مَعَ النَّاسِ. (ق,د,ت,ن,جه)', 'ഉമ്മുഅത്വിയ്യ(റ): നബി(സ) രണ്ടു പെരുന്നാളിലും മറയിലിരിക്കുന്ന യുവതികളെ മുസ്വല്ലയിലേക്ക് (നിസ്കാര സ്ഥലത്തേക്ക്) കൊണ്ടുവരാൻ ഞങ്ങളോട് കൽപിച്ചിരുന്നു. അപ്പോൾ ഒരാൾ നബി(സ)യോടു ചോദിച്ചു: ആർത്തവകാരിയോ? നബി(സ) പറഞ്ഞു: "അവർ നന്മ ചെയ്യുന്നതിലും മുസ്ലിംകളുടെ പ്രാർത്ഥനകളിലും പങ്കെടുക്കണം." ഒരു സ്ത്രീ ചോദിച്ചു: മൂടുപടം ഇല്ലാത്ത സ്ത്രീകളോ? നബി(സ) പറഞ്ഞു: "അവളുടെ സഹോദരി അവളുടെ വസ്ത്രങ്ങളിലൊന്ന് അവൾക്കു നൽകട്ടെ." ഒരു റിപ്പോർട്ടിൽ: നബി(സ) പറഞ്ഞു: "ആർത്തവകാരികൾ മുസ്ലിംകളുടെ നിസ്കാരത്തിൽ നിന്ന് അകന്നു നിൽക്കട്ടെ" വസ്ത്രത്തിന്റെ കാര്യം പറഞ്ഞില്ല. മറ്റൊരു നിവേദനം: ഞങ്ങളോട് ഇക്കാര്യം കൽപിക്കപ്പെട്ടിരുന്നു. മഹതി പറഞ്ഞു: അവർ (ആർത്തവകാരികൾ) നിസ്കരിക്കുന്നവരുടെ പിന്നിൽ നിൽക്കാറുണ്ടായിരുന്നു. ജനങ്ങളോടൊപ്പം അവരും തക്ബീർ ചൊല്ലാറുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅത്വിയ്യ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=15), 1, 'وَفِي رِوَايَةٍ: قَالَ: "وَيَعْتَزِلُ الْحُيَّضُ مُصَلَّى الْمُسْلِمِينَ". وَلَمْ يَذْكُرِ الثَّوْبَ.', 'മറ്റൊരു നിവേദനം: ഞങ്ങളോട് ഇക്കാര്യം കൽപിക്കപ്പെട്ടിരുന്നു. മഹതി പറഞ്ഞു: അവർ (ആർത്തവകാരികൾ) നിസ്കരിക്കുന്നവരുടെ പിന്നിൽ നിൽക്കാറുണ്ടായിരുന്നു. ജനങ്ങളോടൊപ്പം അവരും തക്ബീർ ചൊല്ലാറുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=15), 2, 'وَفِي رِوَايَةٍ: قَالَتْ: كُنَّا نُؤْمَرُ بِهَذَا الْخَبَرِ. قَالَتْ: وَالْحُيَّضُ يَكُنَّ خَلْفَ النَّاسِ، فَيُكَبِّرْنَ مَعَ النَّاسِ. (ق,د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أُمِّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمَّا قَدِمَ الْمَدِينَةَ جَمَعَ نِسَاءَ الْأَنْصَارِ فِي بَيْتٍ، فَأَرْسَلَ إِلَيْنَا عُمَرَ بْنَ الْخَطَّابِ. فَقَامَ عَلَى الْبَابِ، فَسَلَّمَ عَلَيْنَا، فَرَدَدْنَا عَلَيْهِ السَّلَامَ ثُمَّ قَالَ: أَنَا رَسُولُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيْكُنَّ، وَأَمَرَنَا بِالْعِيدَيْنِ أَنْ نُخْرِجَ فِيهِمَا الْحُيَّضَ وَالْعُتَّقَ، وَلَا جُمُعَةَ عَلَيْنَا، وَنَهَانَا عَنِ اتِّبَاعِ الْجَنَائِزِ. (د)', 'ഉമ്മുഅത്വിയ്യ(റ): നബി(സ) മദീനയിൽ വന്നപ്പോൾ അൻസ്വാരി സ്ത്രീകളെ ഒരു വീട്ടിൽ ഒരുമിച്ചു കൂട്ടി. ഞങ്ങളുടെ അടുത്തേക്ക് ഉമറുബ്നുൽ ഖത്വാബി(റ)നെ പറഞ്ഞയച്ചു. അദ്ദേഹം വാതിൽക്കൽ വന്നു നിന്നു, ഞങ്ങളോട് സലാം ചൊല്ലി. ഞങ്ങൾ സലാം മടക്കി. ശേഷം പറഞ്ഞു: നിങ്ങളിലേക്ക് അല്ലാഹുവിന്റെ റസൂൽ അയച്ച ദൂതനാണു ഞാൻ. നബി(സ) ഞങ്ങളോട് രണ്ട് പെരുന്നാളുകളിൽ ആർത്തവകാരികളെയും പ്രായപൂർത്തിയായ ബാലികമാരെയും കൊണ്ടുപോകാൻ കൽപിച്ചു. ഞങ്ങളുടെ മേൽ ജുമുഅഃ ഇല്ല. ജനാസയെ അനുഗമിക്കുന്നതിൽ നിന്ന് ഞങ്ങളെ വിലക്കുകയും ചെയ്തു. (ദ)', 'أُمِّ عَطِيَّةَ', 'ഉമ്മുഅത്വിയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُخْرِجُ بَنَاتِهِ وَنِسَاءَهُ فِي الْعِيدَيْنِ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) തന്റെ പെൺമക്കളെയും ഭാര്യമാരെയും രണ്ട് പെരുന്നാളുകളിലും കൊണ്ടുപോയിരുന്നു. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ رَضِيَ اللهُ عَنْهُ قَالَ: لَقِيتُ أُمَّ عَطِيَّةَ رَضِيَ اللهُ عَنْهَا فَقُلْتُ لَهَا: هَلْ سَمِعْتِ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - وَكَانَتْ إِذَا ذَكَرَتْهُ قَالَتْ: بِأَبِي - قَالَ: "أَخْرِجُوا الْعَوَاتِقَ وَذَوَاتِ الْخُدُورِ، فَيَشْهَدْنَ الْعِيدَ وَدَعْوَةَ الْمُسْلِمِينَ، وَلْيَعْتَزِلِ الْحُيَّضُ مُصَلَّى النَّاسِ". (ن)', 'മുഹമ്മദുബ്നു സീരീൻ(റ): ഞാൻ ഉമ്മുഅത്വിയ്യ(റ)യെ കണ്ടു. അവരോട് ഞാൻ ചോദിച്ചു: നിങ്ങൾ നബി(സ)യിൽ നിന്ന് ഇപ്രകാരം കേട്ടിട്ടുണ്ടോ? - അവർ നബി(സ)യെക്കുറിച്ച് പറയുമ്പോഴും കേൾക്കുമ്പോഴുമെല്ലാം ''എന്റെ പിതാവ് അവിടുത്തേക്ക് പ്രായശ്ചിത്തമായിരിക്കട്ടെ'' എന്ന് പറയാറുണ്ട് - നബി(സ) പറഞ്ഞു: "നിങ്ങൾ കന്യകമാരെയും, അന്തഃപുരവാസികളെയും (മറയിൽ കഴിയുന്നവർ) പെരുന്നാൾ ദിവസം പറഞ്ഞയക്കുക. അവർ പെരുന്നാളുകളിലും മുസ്ലിംകളുടെ പ്രാർത്ഥനകളിലും ഹാജരാകട്ടെ. എന്നാൽ ആർത്തവമുള്ള സ്ത്രീകൾ മുസ്വല്ലയിൽ (നിസ്കാര സ്ഥലം) നിന്ന് വിട്ടുനിൽക്കട്ടെ." (ന)', 'مُحَمَّدِ بْنِ سِيرِينَ', 'മുഹമ്മദുബ്നു സീരീൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 668, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: شَهِدْتُ صَلَاةَ الْفِطْرِ مَعَ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ رَضِيَ اللهُ عَنْهُمْ، فَكُلُّهُمْ يُصَلِّيهَا قَبْلَ الْخُطْبَةِ ثُمَّ يَخْطُبُ، قَالَ: فَنَزَلَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَأَنِّي أَنْظُرُ إِلَيْهِ حِينَ يُجَلِّسُ الرِّجَالَ بِيَدِهِ، ثُمَّ أَقْبَلَ يَشُقُّهُمْ حَتَّى جَاءَ النِّسَاءَ وَمَعَهُ بِلَالٌ، فَقَالَ: {يَا أَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَى أَنْ لَا يُشْرِكْنَ بِاللهِ شَيْئًا} فَتَلَا هَذِهِ الْآيَةَ حَتَّى فَرَغَ مِنْهَا، ثُمَّ قَالَ حِينَ فَرَغَ مِنْهَا: "أَنْتُنَّ عَلَى ذَلِكَ". فَقَالَتِ امْرَأَةٌ وَاحِدَةٌ لَمْ يُجِبْهُ غَيْرُهَا مِنْهُنَّ: نَعَمْ يَا نَبِيَّ اللهِ، لَا يُدْرَى حِينَئِذٍ مَنْ هِيَ. قَالَ: "فَتَصَدَّقْنَ". فَبَسَطَ بِلَالٌ ثَوْبَهُ، ثُمَّ قَالَ: "هَلُمَّ فِدًى لَكُنَّ أَبِي وَأُمِّي". فَجَعَلْنَ يُلْقِينَ الْفَتَخَ وَالْخَوَاتِمَ فِي ثَوْبِ بِلَالٍ. (ق)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ), അബൂബക്കർ(റ), ഉമർ(റ), ഉസ്മാൻ(റ) എന്നിവരോടൊപ്പം ഞാൻ ചെറിയ പെരുന്നാൾ നിസ്കാരത്തിൽ പങ്കെടുത്തിട്ടുണ്ട്. അവരെല്ലാം ആദ്യം നിസ്കാരവും പിന്നീട് പ്രസംഗവുമാണ് നിർവ്വഹിച്ചിരുന്നത്. അദ്ദേഹം തുടർന്നു പറഞ്ഞു: ആളുകളെ അവരവരുടെ ഇരിപ്പിടത്തിൽ ഇരിക്കാൻ കൈകൊണ്ട് നിർദ്ദേശം നൽകി നബി(സ) മിമ്പറിൽ നിന്നിറങ്ങുകയും ബിലാലി(റ)നോടൊപ്പം അവരുടെ ഇടയിലൂടെ സ്ത്രീകളുടെ സമീപം എത്തുകയും ചെയ്യുന്നത് ഞാൻ കണ്ടിരുന്നു. പിന്നീട്: ''നബിയേ, അല്ലാഹുവിന് യാതൊരു പങ്കുകാരെയും നിശ്ചയിക്കുകയില്ലെന്ന് പ്രതിജ്ഞ ചെയ്യുന്നവരായി വിശ്വാസിനികളായ സ്ത്രീകൾ താങ്കളുടെ സമീപം വന്നാൽ'' എന്ന ആയത്ത് നബി(സ) ഓതി. ശേഷം നബി(സ) ചോദിച്ചു: "നിങ്ങളെല്ലാം ഇപ്രകാരം നിലകൊള്ളുന്നവരല്ലേ?" അപ്പോൾ അക്കൂട്ടത്തിൽ ഒരു സ്ത്രീ മാത്രം മറുപടി പറഞ്ഞു: അതെ നബിയേ. ആ സ്ത്രീ ആരായിരുന്നുവെന്ന് ആർക്കും അറിയില്ലായിരുന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ധർമ്മം ചെയ്യുക." അപ്പോൾ ബിലാൽ(റ) തന്റെ വസ്ത്രം നിവർത്തിപ്പിടിച്ചു നബി(സ) പറഞ്ഞു: "എന്റെ പിതാവും മാതാവും നിങ്ങൾക്ക് പ്രായശ്ചിത്തമായിരിക്കട്ടെ, മുന്നോട്ടു വരൂ." ഇതു കേട്ടയുടനെ, സ്ത്രീകൾ മോതിരങ്ങൾ (കല്ലുള്ളതും ഇല്ലാത്തതും) അഴിച്ച് ബിലാലി(റ)ന്റെ വസ്ത്രത്തിൽ ഇടാൻ തുടങ്ങി. (ബു,മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 668, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ النَّحْرِ بَعْدَ الصَّلَاةِ. (ن)', 'ബറാഉബ്നു ആസിബ്(റ): ബലി പെരുന്നാൾ ദിവസം നിസ്കാര ശേഷം നബി(സ) ഞങ്ങൾക്ക് ഖുതുബ നിർവ്വഹിച്ചു. (ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 668, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبَا بَكْرٍ وَعُمَرَ رَضِيَ اللهُ عَنْهُمَا كَانُوا يُصَلُّونَ الْعِيدَيْنِ قَبْلَ الْخُطْبَةِ. (ق,د,ت,جه)', 'ഇബ്നുഉമർ(റ): രണ്ടു പെരുന്നാൾ നിസ്കാരങ്ങൾ നബി(സ)യും, അബൂബക്കർ(റ)വും, ഉമർ(റ)വും നിർവ്വഹിച്ചിരുന്നത് ഖുതുബക്കു മുമ്പായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَخْرَجَ مَرْوَانُ الْمِنْبَرَ فِي يَوْمِ عِيدٍ. فَبَدَأَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ، فَقَامَ رَجُلٌ فَقَالَ: يَا مَرْوَانُ، خَالَفْتَ السُّنَّةَ. أَخْرَجْتَ الْمِنْبَرَ فِي يَوْمِ عِيدٍ، وَلَمْ يَكُنْ يُخْرَجُ فِيهِ. وَبَدَأْتَ بِالْخُطْبَةِ قَبْلَ الصَّلَاةِ. فَقَالَ أَبُو سَعِيدٍ الْخُدْرِيُّ: مَنْ هَذَا؟ قَالُوا: فُلَانُ بْنُ فُلَانٍ. فَقَالَ: أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ رَأَى مُنْكَرًا، فَاسْتَطَاعَ أَنْ يُغَيِّرَهُ بِيَدِهِ، فَلْيُغَيِّرْهُ بِيَدِهِ. فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ". (م,د,ت,ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): പെരുന്നാൾ ദിവസം മർവാൻ മിമ്പർ പുറത്തിറക്കി. അദ്ദേഹം നിസ്കാരത്തിനു മുമ്പ് ഖുത്വുബ തുടങ്ങി. അപ്പോൾ ഒരാൾ എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: മർവാൻ, താങ്കൾ സുന്നത്തിന് എതിരു ചെയ്തിരിക്കുന്നു. പെരുന്നാൾ ദിവസം മിമ്പർ പുറത്തെടുത്തിരിക്കുന്നു. അത് എടുക്കാറുണ്ടായിരുന്നില്ല. താങ്കൾ നിസ്കാരത്തിനു മുമ്പ് ഖുത്വുബ തുടങ്ങിയിരിക്കുന്നു. (അങ്ങനെ പ്രവാചകൻ(സ) തുടങ്ങാറുണ്ടായിരുന്നില്ല). അബൂസഈദ്(റ) പറഞ്ഞു: ആരാണ് ഇത് പറയുന്നത്? അവർ പറഞ്ഞു: ഇന്നവന്റെ മകനാണ്. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഈ വ്യക്തി തന്റെ കടമ നിർവ്വഹിച്ചിരിക്കുന്നു. നബി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും വെറുക്കപ്പെട്ട ഒരുകാര്യം കാണുകയും, അതിനെ കൈ കൊണ്ട് മാറ്റാൻ കഴിയുകയും ചെയ്താൽ അതിനെ കൈ കൊണ്ട് മാറ്റട്ടെ. അതിനു സാധിച്ചില്ലെങ്കിൽ അതിനെ നാവുകൊണ്ട് തടയട്ടെ. അതിനും സാധിച്ചില്ലെങ്കിൽ അവൻ അതിനെ ഹൃദയം കൊണ്ട് വെറുക്കട്ടെ. അത് ഈമാനിന്റെ ഏറ്റവും താഴ്ന്ന പടിയാണ്." (മു,ദ,തു,ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ سَمِعْتُهُ يَقُولُ: إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ يَوْمَ الْفِطْرِ، فَصَلَّى فَبَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ، ثُمَّ خَطَبَ النَّاسَ. فَلَمَّا فَرَغَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَزَلَ، فَأَتَى النِّسَاءَ، فَذَكَّرَهُنَّ. وَهُوَ يَتَوَكَّأُ عَلَى يَدِ بِلَالٍ. وَبِلَالٌ بَاسِطٌ ثَوْبَهُ، تُلْقِي فِيهِ النِّسَاءُ الصَّدَقَةَ. قَالَ: تُلْقِي الْمَرْأَةُ فَتَخَهَا، وَيُلْقِينَ وَيُلْقِينَ. وَقَالَ ابْنُ بَكْرٍ: فَتَخَتَهَا. (د,ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) ചെറിയ പെരുന്നാൾ ദിവസം ഖുത്വുബക്കു മുമ്പ് നിസ്കരിച്ചു. പിന്നെ ഖുത്വുബ നിർവ്വഹിച്ചു. ഖുത്വുബ കഴിഞ്ഞപ്പോൾ നബി(സ) ഇറങ്ങി വന്ന് സ്ത്രീകളുടെ അടുത്തു ചെന്നു. അവരെ ഉപദേശിച്ചു. നബി(സ) ബിലാലി(റ)ന്റെ കയ്യിൽ ചാരിയിരുന്നു. ബിലാൽ(റ) വസ്ത്രം (തട്ടം) വിരിച്ചിരുന്നു. സ്ത്രീകൾ അതിൽ സ്വദഖ ഇടുന്നുണ്ടായിരുന്നു. റിപ്പോർട്ടർ പറയുന്നു: സ്ത്രീകൾ മോതിരങ്ങളും മറ്റും ഇടുന്നുണ്ടായിരുന്നു. (ദ,ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: شَهِدَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ خَرَجَ يَوْمَ فِطْرٍ فَصَلَّى، ثُمَّ خَطَبَ. ثُمَّ أَتَى النِّسَاءَ وَمَعَهُ بِلَالٌ، وَأَمَرَهُنَّ بِالصَّدَقَةِ. فَجَعَلْنَ تُلْقِينَ. وَفِي رِوَايَةٍ قَالَ: فَظَنَّ أَنَّهُ لَمْ يُسْمِعِ النِّسَاءَ، فَمَشَى إِلَيْهِنَّ وَبِلَالٌ مَعَهُ، فَوَعَظَهُنَّ وَأَمَرَهُنَّ بِالصَّدَقَةِ. فَكَانَتِ الْمَرْأَةُ تُلْقِي الْقُرْطَ، وَالْخَاتَمَ فِي ثَوْبِ بِلَالٍ. وَفِي رِوَايَةٍ قَالَ: فَجَعَلَتِ الْمَرْأَةُ تُعْطِي الْقُرْطَ وَالْخَاتَمَ، وَجَعَلَ بِلَالٌ يَجْعَلُهُ فِي كِسَائِهِ. قَالَ: "فَقَسَمَهُ عَلَى فُقَرَاءِ الْمُسْلِمِينَ". (ق,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ചെറിയ പെരുന്നാൾ ദിവസം നിസ്കാര സ്ഥലത്തേക്കു പുറപ്പെട്ടുവെന്നതിന്നും നിസ്കരിക്കുകയും പിന്നീട് ഖുത്വുബ നിർവ്വഹിക്കുകയും ചെയ്തുവെന്നതിന്നും പിന്നീട് ബിലാലി(റ)നോടൊപ്പം സ്ത്രീകളുടെ അടുത്ത് ചെന്നുവെന്നതിന്നും, അവരോട് ദാനധർമ്മങ്ങൾ നൽകാൻ കൽപിച്ചുവെന്നതിന്നും, അവർ വസ്ത്രത്തിൽ (ധാനം) ഇട്ടുവെന്നതിനും അദ്ദേഹം സാക്ഷിയായി.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=24), 1, 'وَفِي رِوَايَةٍ قَالَ: فَظَنَّ أَنَّهُ لَمْ يُسْمِعِ النِّسَاءَ، فَمَشَى إِلَيْهِنَّ وَبِلَالٌ مَعَهُ، فَوَعَظَهُنَّ وَأَمَرَهُنَّ بِالصَّدَقَةِ. فَكَانَتِ الْمَرْأَةُ تُلْقِي الْقُرْطَ، وَالْخَاتَمَ فِي ثَوْبِ بِلَالٍ.', 'മറ്റൊരു നിവേദനിൽ: സ്ത്രീകൾ കമ്മലും മോതിരവും നൽകാൻ തുടങ്ങി. ബിലാൽ(റ) അത് തന്റെ വിരിപ്പിൽ വെക്കാനും തുടങ്ങി. അങ്ങനെ അത് മുസ്ലിംകളിലെ ദരിദ്രർക്ക് വീതിച്ചുനൽകി. (ബു,മു,ദ,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=24), 2, 'وَفِي رِوَايَةٍ قَالَ: فَجَعَلَتِ الْمَرْأَةُ تُعْطِي الْقُرْطَ وَالْخَاتَمَ، وَجَعَلَ بِلَالٌ يَجْعَلُهُ فِي كِسَائِهِ. قَالَ: "فَقَسَمَهُ عَلَى فُقَرَاءِ الْمُسْلِمِينَ". (ق,د,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنِ ابْنِ عَبَّاسٍ وَ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمْ قَالَا: لَمْ يَكُنْ يُؤَذَّنُ يَوْمَ الْفِطْرِ وَلَا يَوْمَ الْأَضْحَى. (ق)', 'ഇബ്നുഅബ്ബാസ്(റ), ജാബിറുബ്നു അബ്ദില്ല(റ): ചെറിയ പെരുന്നാളിനും, ബലിപെരുന്നാളിനും ബാങ്കു വിളിക്കാറില്ല. (ബു,മു)', 'ابْنِ عَبَّاسٍ وَ جَابِرِ بْنِ عَبْدِ اللهِ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 670, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعِيدَيْنِ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ، بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ. (م)', 'ജാബിറിബ്നു സമുറ(റ): ഞാൻ നബി(സ)യോടൊപ്പം ബാങ്കോ ഇഖാമത്തോ കൂടാതെ പലപ്രാവശ്യം രണ്ടു പെരുന്നാൾ നിസ്കാരവും നിർവ്വഹിച്ചിട്ടുണ്ട്. (മു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറിബ്നു സമുറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 670, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي عِيدٍ قَبْلَ الْخُطْبَةِ، بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ. (ن)', 'ജാബിർ(റ): ബാങ്കോ, ഇഖാമത്തോ കൂടാതെ നബി(സ) ഖുതുബക്കു മുമ്പായി പെരുന്നാൾ നിസ്കാരം ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചിട്ടുണ്ട്. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 670, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: سَأَلَهُ رَجُلٌ: أَشَهِدْتَ الْعِيدَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، وَلَوْلَا مَنْزِلَتِي مِنْهُ مَا شَهِدْتُهُ مِنَ الصِّغَرِ. فَأَتَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَلَمَ الَّذِي عِنْدَ دَارِ كَثِيرِ بْنِ الصَّلْتِ، فَصَلَّى ثُمَّ خَطَبَ، وَلَمْ يَذْكُرْ أَذَانًا وَلَا إِقَامَةً، قَالَ: ثُمَّ أَمَرَنَا بِالصَّدَقَةِ. قَالَ: فَجَعَلَ النِّسَاءُ يُشِرْنَ إِلَى آذَانِهِنَّ، وَحُلُوقِهِنَّ. قَالَ: فَأَمَرَ بِلَالًا، فَأَتَاهُنَّ، ثُمَّ رَجَعَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ അദ്ദേഹത്തോട് ചോദിച്ചു: നബി(സ)യോടൊപ്പം താങ്കൾ പെരുന്നാൾ നിസ്കാരത്തിനായി പോയിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ, എനിക്ക് നബി(സ)യുടെ അടുക്കൽ പ്രത്യേക സ്ഥാനം ഇല്ലായിരുന്നുവെങ്കിൽ ഞാൻ എന്റെ ചെറുപ്രായത്തിൽ കൂടെപ്പോകുമായിരുന്നില്ല. കസീറുബ്നു സ്വൽതിന്റെ വീടിനടുത്തുള്ള (പ്രത്യേകം അടയാളപ്പെടുത്തിയ) ഉയർന്ന സ്ഥലത്തു ചെന്ന് നബി(സ) നിസ്കരിക്കുകയും തുടർന്ന് ഖുതുബ നിർവ്വഹിക്കുകയും ചെയ്തു. ബാങ്കും ഇഖാമത്തുമൊന്നും വിളിച്ചില്ല. ശേഷം ഞങ്ങളോട് നബി(സ) സ്വദഖ ചെയ്യാൻ കൽപിച്ചു. അപ്പോൾ സ്ത്രീകൾ അവരുടെ കാതുകളിലേക്കും കഴുത്തിലേക്കും (ആഭരണങ്ങളെടുക്കാൻ) കൈ നീട്ടി. അപ്പോൾ നബി(സ) ബിലാലി(റ)നോട് അവരുടെ അടുത്തു ചെല്ലാൻ പറഞ്ഞു. അങ്ങനെ അദ്ദേഹം പോവുകയും ശേഷം നബി(സ)യുടെ അടുത്തേക്ക് മടങ്ങുകയും ചെയ്തു. (ബു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 670, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى الْعِيدَ بِلَا أَذَانٍ وَلَا إِقَامَةٍ، وَأَبَا بَكْرٍ وَعُمَرَ، أَوْ عُثْمَانَ. (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യും, അബൂബക്കറും(റ), ഉമറും(റ), ഉസ്മാനും(റ) ബാങ്കോ ഇഖാമത്തോ കൂടാതെ പെരുന്നാൾ നിസ്കാരം നിർവ്വഹിച്ചു. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 670, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ الصَّلَاةَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي يَوْمِ عِيدٍ، فَبَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ، بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ، فَلَمَّا قَضَى الصَّلَاةَ قَامَ مُتَوَكِّئًا عَلَى بِلَالٍ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، وَوَعَظَ النَّاسَ وَذَكَّرَهُمْ وَحَثَّهُمْ عَلَى طَاعَتِهِ، ثُمَّ مَالَ وَمَضَى إِلَى النِّسَاءِ وَمَعَهُ بِلَالٌ، فَأَمَرَهُنَّ بِتَقْوَى اللهِ وَوَعَظَهُنَّ وَذَكَّرَهُنَّ، وَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، ثُمَّ حَثَّهُنَّ عَلَى طَاعَتِهِ، ثُمَّ قَالَ: "تَصَدَّقْنَ، فَإِنَّ أَكْثَرَكُنَّ حَطَبُ جَهَنَّمَ". فَقَالَتِ امْرَأَةٌ مِنْ سَفِلَةِ النِّسَاءِ، سَفْعَاءُ الْخَدَّيْنِ: بِمَ يَا رَسُولَ اللهِ؟ قَالَ: "تُكْثِرْنَ الشَّكَاةَ، وَتَكْفُرْنَ الْعَشِيرَ". فَجَعَلْنَ يَنْزِعْنَ قَلَائِدَهُنَّ وَأَقْرِطَهُنَّ وَخَوَاتِيمَهُنَّ، يَقْذِفْنَهُ فِي ثَوْبِ بِلَالٍ، يَتَصَدَّقْنَ بِهِ. (ن)', 'ജാബിർ(റ): ഒരു പെരുന്നാൾ ദിവസം നബി(സ)യോടൊപ്പം ഞാൻ നിസ്കാരത്തിൽ പങ്കെടുത്തു. ഖുതുബക്ക് മുമ്പ് നബി(സ) ബാങ്കോ ഇഖാമത്തോ കൂടാതെ നിസ്കരിച്ചു. നിസ്കാരം കഴിഞ്ഞ് നബി(സ) ബിലാൽ(റ)നെ ചാരിക്കൊണ്ട് എഴുന്നേറ്റുനിന്ന് ഖുതുബ നിർവ്വഹിച്ചു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും പ്രശംസിക്കുകയും ചെയ്തശേഷം ജനങ്ങൾക്ക് ഉപദേശം നൽകുകയും അല്ലാഹുവിനെ അനുസരിക്കുവാൻ പ്രേരിപ്പിക്കുകയും ചെയ്തു. തുടർന്ന് ബിലാലി(റ)നോടപ്പം സ്ത്രീകളെ സമീപിച്ച് അല്ലാഹുവിനെ സൂക്ഷിക്കാൻ കൽപിച്ചു. (വിധിവിലക്കുകൾ) അവരെ ഓർമ്മപ്പെടുത്തുകയും ഉപദേശം നൽകുകയും ചെയ്തു. അല്ലാഹുവിനെ സ്തുതിക്കുകയും പ്രശംസിക്കുകയും ചെയ്തശേഷം അവനെ അനുസരിക്കുവാൻ അവരെ പ്രേരിപ്പിച്ചു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ദാനധർമ്മം ചെയ്യുക. നിങ്ങളിൽ അധികപേരും നരകത്തിനുള്ള വിറകുകളാണ്." അപ്പാൾ വിളറിയ കവിളുകളോടു കൂടിയ ഒരു സ്ത്രീ നബി(സ)യോടു ചോദിച്ചു: എന്തുകൊണ്ടാണ് (അവർ നരകത്തിലെ വിറകുകളാകുന്നത്) അല്ലാഹുവിന്റെ റസൂലേ? നബി(സ) പ്രതിവചിച്ചു: "നിങ്ങൾ പരാതി വർദ്ധിപ്പിക്കുകയും, ഭർത്താക്കന്മാരെ ധിക്കരിക്കുകയും ചെയ്യുന്നു." അപ്പോൾ അവർ തങ്ങളുടെ മാലകളും, കമ്മലുകളും, മോതിരങ്ങളും ഊരി ബിലാലി(റ)ന്റെ (നിവർത്തിപ്പിടിച്ച) വസ്ത്രത്തിൽ ഇടാൻ തുടങ്ങി. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْرُجُ يَوْمَ الْفِطْرِ وَيَوْمَ الْأَضْحَى إِلَى الْمُصَلَّى، فَيُصَلِّي بِالنَّاسِ، فَإِذَا جَلَسَ فِي الثَّانِيَةِ وَسَلَّمَ قَامَ فَاسْتَقْبَلَ النَّاسَ بِوَجْهِهِ وَالنَّاسُ جُلُوسٌ، فَإِنْ كَانَتْ لَهُ حَاجَةٌ: يُرِيدُ أَنْ يَبْعَثَ بَعْثًا ذَكَرَهُ لِلنَّاسِ، وَإِلَّا أَمَرَ النَّاسَ بِالصَّدَقَةِ. قَالَ: "تَصَدَّقُوا" ثَلَاثَ مَرَّاتٍ، فَكَانَ مِنْ أَكْثَرِ مَنْ يَتَصَدَّقُ النِّسَاءُ. (ن)', 'അബൂസഈദുൽ ഖുദ്രി(റ): ചെറിയ പെരുന്നാൾ ദിവസവും ബലിപെരുന്നാൾ ദിവസവും നിസ്കാരം നിർവ്വഹിക്കാൻ നബി(സ) മുസ്വല്ലയിൽ എത്തുകയും ആളുകൾക്ക് ഇമാമായി നിസ്കരിക്കുകയും ചെയ്യും. രണ്ടാമത്തെ റക്അത്തിൽ ഇരുന്ന് സലാം വീട്ടിയശേഷം എഴുന്നേൽക്കുകയും ജനങ്ങളെ അഭിമുഖീകരിച്ച് നിൽക്കുകയും ചെയ്യും. ആളുകൾ ഇരിക്കുകയായിരിക്കും. ഏതെങ്കിലും ഭാഗത്തേക്ക് സൈന്യത്തെ അയക്കാനുദ്ദേശിക്കുന്നുവെങ്കിൽ ആ വിവരം ജനങ്ങളെ അറിയിക്കും. അല്ലെങ്കിൽ ദാനധർമ്മം ചെയ്യുവാൻ ഉപദേശിക്കും. നബി(സ) "നിങ്ങൾ ദാനധർമ്മം നൽകൂ." എന്ന് മൂന്നുപ്രാവശ്യം പറയും. അങ്ങനെ ധർമ്മം നൽകുന്നവരിൽ കൂടുതലും സ്ത്രീകളായിരിക്കും. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي كَاهِلٍ الْأَحْمَسِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى نَاقَةٍ، وَحَبَشِيٌّ آخِذٌ بِخِطَامِ النَّاقَةِ. (ن)', 'അബൂകാഹിലുൽ അഹ്മസി(റ): നബി(സ) ഒരു ഒട്ടകപ്പുറത്തിരുന്ന് പ്രസംഗിക്കുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഒരു നീഗ്രോ അടിമ ഒട്ടകത്തിന്റെ മൂക്കുകയർ പിടിച്ചുകൊണ്ട് നിന്നിരുന്നു. (ന)', 'أَبِي كَاهِلٍ الْأَحْمَسِيِّ', 'അബൂകാഹിലുൽ അഹ്മസി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ نُبَيْطِ بْنِ شَرِيطٍ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ حَجَّ فَقَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى بَعِيرِهِ. (د,ن,جه)', 'നുബൈത്ത്(റ): അദ്ദേഹം ഹജ്ജ് ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: പ്രവാചകൻ(സ) തന്റെ ഒട്ടപ്പുറത്തിരുന്നു ഖുതുബ നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടു. (ദ,ന,ജ)', 'نُبَيْطِ بْنِ شَرِيطٍ الْأَشْجَعِيِّ', 'നുബൈത്ത്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَاةُ الْأَضْحَى رَكْعَتَانِ، وَصَلَاةُ الْفِطْرِ رَكْعَتَانِ، وَصَلَاةُ الْمُسَافِرِ رَكْعَتَانِ، وَصَلَاةُ الْجُمُعَةِ رَكْعَتَانِ، تَمَامٌ لَيْسَ بِقَصْرٍ، عَلَى لِسَانِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ഉമർ(റ): ചെറിയ പെരുന്നാൾ നിസ്കാരവും, ബലിപെരുന്നാൾ നിസ്കാരവും, യാത്രക്കാരന്റെ നിസ്കാരവും, ജുമുഅഃ നിസ്കാരവും ഈരണ്ട് റക്അത്തുകൾ ആണ്. അത് പൂർണ്ണമാണ്. ചുരുക്ക(ഖസ്ർ)മല്ല. ഇത് നബി(സ)യുടെ നാവിലൂടെ ചര്യയാക്കപ്പെട്ടതാണ്. (ന)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عُمَرَ ابْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ سَأَلَ أَبَا وَاقِدٍ اللَّيْثِيَّ: مَا كَانَ يَقْرَأُ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْأَضْحَى وَالْفِطْرِ؟ فَقَالَ: كَانَ يَقْرَأُ فِيهِمَا ب {ق. وَالْقُرْآنِ الْمَجِيدِ} وَ{اقْتَرَبَتِ السَّاعَةُ وَانْشَقَّ الْقَمَرُ}. (م,د,ت,ن,جه)', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദുല്ല(റ): ഉമർ(റ) അബൂവാഖിദുല്ലൈസീ(റ)യോടു ചോദിച്ചു: ചെറിയ പെരുന്നാൾ നിസ്കാരത്തിലും ബലിപെരുന്നാൾ നിസ്കാരത്തിലും നബി(സ) എന്തായിരുന്നു ഓതിയിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: ''ഖാഫ്, വൽ ഖുർആനിൽ മജീദ്'', ''ഇഖ്തറബതി സ്സാഅതു...'' എന്നീ സൂറത്തുകളാണ് അവിടുന്ന് അവയിൽ ഓതിയിരുന്നത്. (മു,ദ,തു,ന,ജ)', 'عُبَيْدِ اللهِ بْنِ عَبْدِ اللهِ', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദുല്ല(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْعِيدَيْنِ وَفِي الْجُمُعَةِ ب: {سبح اسم ربك الْأَعْلَى} وَ {هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ} وَرُبَّمَا اجْتَمَعَا فِي يَوْمٍ وَاحِدٍ فَيَقْرَأُ. (م,د,ت,ن,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): നബി(സ) രണ്ട് പെരുന്നാൾ നിസ്കാരത്തിലും "سبح اسم ربك...."യും, "هل أتاك..."യും ഓതാറുണ്ടായിരുന്നു. ചിലപ്പോൾ ഒരു ദിവസം തന്നെ ജുമുഅയും പെരുന്നാളും ഒന്നിച്ചുവരും. അപ്പോഴും ഇവരണ്ടും ഓതും. (മു,ദ,തു,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ ثَعْلَبَةَ بْنِ زَهْدَمٍ: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ اسْتَخْلَفَ أَبَا مَسْعُودٍ رَضِيَ اللهُ عَنْهُ عَلَى النَّاسِ، فَخَرَجَ يَوْمَ عِيدٍ فَقَالَ: يَا أَيُّهَا النَّاسُ، إِنَّهُ لَيْسَ مِنَ السُّنَّةِ أَنْ يُصَلَّى قَبْلَ الْإِمَامِ. (ن)', 'സഅ്‌ലബത്‌ബ്‌നു സഹ്ദം(റ): അലി(റ), അബൂമസ്‌ഊദി(റ)നെ (നിസ്‌കാര നിർവ്വഹണത്തിന്) തന്റെ പ്രതിനിധിയായി നിശ്ചയിച്ചു. അദ്ദേഹം പെരുന്നാൾ നിസ്‌കാരത്തിന് നേതൃത്വം നൽകാൻ വന്നു. അദ്ദേഹം പറഞ്ഞു: ജനങ്ങളെ, ഇമാം നിസ്‌കരിക്കുന്നതിന് മുമ്പ് നിസ്‌കരിക്കൽ സുന്നത്തിൽപെട്ടതല്ല. (ന)', 'ثَعْلَبَةَ بْنِ زَهْدَمٍ', 'സഅ്‌ലബത്‌ബ്‌നു സഹ്ദം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي رِمْثَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ وَعَلَيْهِ بُرْدَانِ أَخْضَرَانِ. (ن)', 'അബൂരിംസ(റ): നബി(സ) പെരുന്നാൾ ഖുതുബ നിർവ്വഹിക്കുന്നത് ഞാൻ കണ്ടു. നബി(സ) പച്ച നിറത്തിലുള്ള രണ്ടു വസ്ത്രങ്ങൾ ധരിച്ചിരുന്നു. (ന)', 'أَبِي رِمْثَةَ', 'അബൂരിംസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قُلْتَ لِصَاحِبِكَ أَنْصِتْ - وَالْإِمَامُ يَخْطُبُ - فَقَدْ لَغَوْتَ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇമാം ഖുതുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ ''ശ്രദ്ധിച്ചു കേൾക്കൂ'' എന്ന് കൂട്ടുകാരനോട് നീ പറഞ്ഞാൽ നിനക്ക് (കൂലി) നഷ്ടമാവും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي خُطْبَتِهِ، يَحْمَدُ اللَّهَ وَيُثْنِي عَلَيْهِ بِمَا هُوَ أَهْلُهُ، ثُمَّ يَقُولُ: "مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ، إِنَّ أَصْدَقَ الْحَدِيثِ كِتَابُ اللهِ، وَأَحْسَنَ الْهَدْيِ هَدْيُ مُحَمَّدٍ، وَشَرَّ الْأُمُورِ مُحْدَثَاتُهَا، وَكُلَّ مُحْدَثَةٍ بِدْعَةٌ، وَكُلَّ بِدْعَةٍ ضَلَالَةٌ، وَكُلَّ ضَلَالَةٍ فِي النَّارِ". ثُمَّ يَقُولُ: "بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ". وَكَانَ إِذَا ذَكَرَ السَّاعَةَ احْمَرَّتْ وَجْنَتَاهُ وَعَلَا صَوْتُهُ وَاشْتَدَّ غَضَبُهُ، كَأَنَّهُ نَذِيرُ جَيْشٍ يَقُولُ: صَبَّحَكُمْ مَسَّاكُمْ. ثُمَّ قَالَ: "مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ، وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَإِلَيَّ، أَوْ: عَلَيَّ، وَأَنَا أَوْلَى بِالْمُؤْمِنِينَ". (ن)', 'ജാബിറുബ്‌നു അബ്ദുല്ല(റ): നബി(സ) പ്രസംഗിക്കുമ്പോൾ അല്ലാഹുവിനെ സ്തുതിക്കുകയും വാഴ്ത്തുകയും ചെയ്തശേഷം ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹു ആരെ നേർമാർഗ്ഗത്തിലാക്കുന്നുവോ അയാളെ വഴിതെറ്റിക്കുന്നവരില്ല. അല്ലാഹു വഴിതെറ്റിക്കുന്നവരെ സന്മാർഗ്ഗത്തിലാക്കാനും ഒരുത്തനുമില്ല. ഏറ്റവും സത്യസന്ധമായ വാക്ക് അല്ലാഹുവിന്റെ ഗ്രന്ഥമാണ്. ഏറ്റവും നല്ല ചര്യ മുഹമ്മദ് നബി(സ)യുടെ ചര്യയാണ്. ഏറ്റവും ചീത്തയായ സംഗതി മതത്തിൽ പുതുതായി ഉണ്ടാക്കുന്ന കാര്യങ്ങളാണ്. പുതുതായി ഉണ്ടാക്കപ്പെട്ടതെല്ലാം (മതത്തിൽ) അനാചാരമാണ്. എല്ലാ അനാചാരങ്ങളും വഴിപിഴച്ചതാണ്. എല്ലാ വഴിപിഴച്ചതും നരകത്തിലാണ്." പിന്നീട് പറയും: "അന്ത്യനാൾ ഇതുപോലെ അടുത്തിരിക്കുന്ന (രണ്ടു വിരലുകൾ അടുപ്പിച്ചുകൊണ്ട്) സന്ദർഭത്തിലാണ് ഞാൻ പ്രവാചകനായി നിയോഗിക്കപ്പെട്ടത്." അന്ത്യനാളിനെക്കുറിച്ച് പറയുമ്പോൾ നബി(സ)യുടെ കവിൾത്തടങ്ങൾ ചുവക്കുകയും ശബ്ദം ഉയരുകയും കോപം വർദ്ധിക്കുകയും ചെയ്യും. പ്രഭാതത്തിലോ പ്രദോഷത്തിലോ അക്രമിക്കുന്ന സൈന്യത്തെക്കുറിച്ച് മുന്നറിയിപ്പ് നൽകുന്നവനെപ്പോലെ അവിടുന്ന് സംസാരിക്കും. ശേഷം പറയും: “ആരെങ്കിലും സമ്പത്ത് അവശേഷിപ്പിച്ചാൽ അത് അവരുടെ കുടുംബാംഗങ്ങൾക്ക് അവകാശപ്പെട്ടതാണ്. കടമോ, നഷ്ടമോ ബാക്കിയായാൽ അത് എനിക്ക് ബാധ്യതയാകുന്നതാണ്. ഞാനാണ് സത്യവിശ്വാസികളോട് കൂടുതൽ കടപ്പെട്ടവൻ.” (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്‌നു അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 673, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ سَعْدِ بْنِ عَائِذٍ الْمُؤَذِّنِ رَضِيَ اللهُ عَنْهُ: كَانَ النَّبِيُّ صَلَّى الله عَلَيْهِ وَسَلَّمَ يُكَبِّرُ بَيْنَ أَضْعَافِ الْخُطْبَةِ، يُكْثِرُ التَّكْبِيرَ فِي خُطْبَةِ الْعِيدَيْنِ. (جه)', 'സഅ്ദുബ്നു ആഇദ്(റ): പ്രവാചകൻ(സ) ഖുതുബക്കിടയിൽ തക്ബീർ ചൊല്ലാറുണ്ടായിരുന്നു. പെരുന്നാൾ ഖുതുബക്കിടയിൽ ധാരാളമായി തക്ബീറുകൾ ഉരുവിടാറുണ്ടായിരുന്നു. (ജ)', 'سَعْدِ بْنِ عَائِذٍ الْمُؤَذِّنِ', 'സഅ്ദുബ്നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ الْحَسَنِ رَضِيَ الله عَنْهُ: أَنَّ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا خَطَبَ بِالْبَصْرَةِ فَقَالَ: أَدُّوا زَكَاةَ صَوْمِكُمْ. فَجَعَلَ النَّاسُ يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ، فَقَالَ: مَنْ هَاهُنَا مِنْ أَهْلِ الْمَدِينَةِ؟ قُومُوا إِلَى إِخْوَانِكُمْ فَعَلِّمُوهُمْ، فَإِنَّهُمْ لَا يَعْلَمُونَ، أَنَّ رَسُولَ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ فَرَضَ صَدَقَةَ الْفِطْرِ عَلَى الصَّغِيرِ وَالْكَبِيرِ، وَالْحُرِّ وَالْعَبْدِ، وَالذَّكَرِ وَالْأُنْثَى، نِصْفَ صَاعٍ مِنْ بُرٍّ، أَوْ صَاعًا مِنْ تَمْرٍ أَوْ شَعِيرٍ. (ن)', 'ഹസൻ(റ): ഇബ്നുഅബ്ബാസ്(റ) ബസറയിൽ ഖുതുബ നിർവ്വഹിച്ചപ്പോൾ പറഞ്ഞു: നിങ്ങളുടെ നോമ്പിന്റെ സക്കാത്ത് (നിർബന്ധദാനം) നൽകുക. ഇതുകേട്ടപ്പോൾ ആളുകൾ പരസ്പരം നോക്കി. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: മദീനാ നിവാസികൾ ആരെങ്കിലും ഇവിടെയുണ്ടോ? ഉണ്ടെങ്കിൽ അവർ എഴുന്നേറ്റ് തങ്ങളുടെ സഹോദരങ്ങളെ ഇക്കാര്യം പഠിപ്പിക്കട്ടെ. അവർക്ക് ഈ വിഷയം സംബന്ധിച്ച് അറിയില്ല. അല്ലാഹുവിന്റെ റസൂൽ(സ) കുട്ടികൾക്കും, പ്രായമുള്ളവർക്കും, സ്വതന്ത്രനും, അടിമക്കും, പുരുഷനും, സ്ത്രീക്കും അര സ്വാഅ് ഗോതമ്പോ, ഒരു സ്വാഅ് കാരയ്ക്കയോ, ഒരു സ്വാഅ് ബാർലിയോ ഫിത്ർ സ്വദഖ (സക്കാത്ത്) നിർബന്ധമാക്കിയിട്ടുണ്ട്. (ന)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أُصَلِّي مَعَ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ، فَكَانَتْ صَلَاتُهُ قَصْدًا وَخُطْبَتُهُ قَصْدًا. (ن)', 'ജാബിറുബ്നു സമുറ(റ): ഞാൻ നബി(സ)യോടൊപ്പം നിസ്കരിച്ചിട്ടുണ്ട്. നബി(സ)യുടെ നിസ്കാരവും, ഖുതുബയും മിതമായിരുന്നു. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنِ ابْنِ بُرَيْدَةَ رَضِيَ الله عَنْهُ قَالَ: بَيْنَا رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ يَخْطُبُ إِذْ أَقْبَلَ الْحَسَنُ وَالْحُسَيْنُ عَلَيْهِمَا السَّلَامُ، عَلَيْهِمَا قَمِيصَانِ أَحْمَرَانِ، يَمْشِيَانِ وَيَعْثُرَانِ، فَنَزَلَ وَحَمَلَهُمَا، فَقَالَ: "صَدَقَ اللَّهُ: {إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ} [التغابن: ١٥]. رَأَيْتُ هَذَيْنِ يَمْشِيَانِ وَيَعْثُرَانِ فِي قَمِيصَيْهِمَا، فَلَمْ أَصْبِرْ حَتَّى نَزَلْتُ فَحَمَلْتُهُمَا". (ن)', 'ഇബ്നുബുറൈദ(റ): നബി(സ) മിമ്പറിൽ നിന്ന് ഖുതുബ നിർവ്വഹിച്ചു കൊണ്ടിരിക്കെ ഹസൻ(റ)വും ഹുസൈൻ(റ)വും കടന്നുവന്നു. അവർ രണ്ട് ചുവന്ന കുപ്പായം ധരിച്ചിരുന്നു. അവർ കാലുറക്കാതെ നടക്കുകയായിരുന്നു. അപ്പോൾ നബി(സ) താഴെയിറങ്ങി അവരെ രണ്ടുപേരെയും എടുത്തു. ശേഷം സൂറത്തുത്തഗാബുനിലെ ''നിങ്ങളുടെ ധനവും, മക്കളും പരീക്ഷണമാണ്'' എന്ന ആയത്ത് ഓതിക്കൊണ്ട് നബി(സ) പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞത് സത്യമാണ്, ഈ രണ്ടുകുട്ടികളും കുപ്പായമണിഞ്ഞ് കാലിടറി നടക്കുന്നതു കണ്ടപ്പോൾ മിമ്പറിൽ നിന്നിറങ്ങി അവരെ എടുക്കാതിരിക്കാൻ എനിക്ക് കഴിഞ്ഞില്ല." (ന)', 'ابْنِ بُرَيْدَةَ', 'ഇബ്നുബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'التغابن: ١٥', null, 674, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَبْدِ اللهِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى الْعِيدَ، قَالَ: "مَنْ أَحَبَّ أَنْ يَنْصَرِفَ فَلْيَنْصَرِفْ، وَمَنْ أَحَبَّ أَنْ يُقِيمَ لِلْخُطْبَةِ فَلْيُقِمْ". (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ): പെരുന്നാൾ നിസ്കാരശേഷം നബി(സ) പറഞ്ഞു: "മടങ്ങാനുദ്ദേശിക്കുന്നവർക്ക് മടങ്ങാം. ഖുത്വുബ ശ്രവിക്കാൻ ഇഷ്ടപ്പെടുന്നവർക്ക് ഇവിടെ ഇരിക്കാം." (ന,ജ)', 'عَبْدِ اللهِ بْنِ السَّائِبِ', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْأَضْحَى، وَانْكَفَأَ إِلَى كَبْشَيْنِ أَمْلَحَيْنِ فَذَبَحَهُمَا. (ن)', 'അനസുബ്നു മാലിക്(റ): ബലിപെരുന്നാൾ ദിവസം നബി(സ) ഖുതുബ നിർവ്വഹിച്ചു. തുടർന്ന് അതിസുന്ദരമായ രണ്ടാടുകളെ അറുത്തു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَذْبَحُ - أَوْ: يَنْحَرُ - بِالْمُصَلَّى. (خ,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) നിസ്കാര സ്ഥലത്ത് വെച്ചുതന്നെ ബലിയറുക്കാറുണ്ടായിരുന്നു. (ബു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ يَوْمُ عِيدٍ خَالَفَ الطَّرِيقَ. (خ)', 'ജാബിർ(റ): പെരുന്നാൾ ദിവസം നബി(സ) (പെരുന്നാൾ നിസ്കാരത്തിന് പോകുന്നതും മടങ്ങുന്നതും) വഴി മാറി നടക്കാറുണ്ടായിരുന്നു. (ബു)', 'جَابِرِ بْنِ عَبْدِاللَّهِ', 'ജാബിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ يَوْمَ الْعِيدِ فِي طَرِيقٍ، ثُمَّ رَجَعَ فِي طَرِيقٍ آخَرَ. (د,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പെരുന്നാൾ നിസ്കാരത്തിന് ഒരു വഴിയിലൂടെ പുറപ്പെടുകയും, മറ്റൊരു വഴിക്ക് മടങ്ങുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ يَوْمَ الْعِيدِ فِي طَرِيقٍ رَجَعَ فِي غَيْرِهِ. حَسَنٌ غَرِيبٌ (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പെരുന്നാൾ ദിവസം ഒരു വഴിയിലൂടെ പുറപ്പെട്ടാൽ മറ്റൊരു വഴിയിലൂടെ മടങ്ങാറുണ്ടായിരുന്നു. ഇതിന്റെ പരമ്പരയിൽ ഹസനും ഗരീബുമുണ്ടെന്ന് തുർമുദി പറയുന്നു. (തു)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 675, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ وَعِنْدِي جَارِيَتَانِ تُغَنِّيَانِ بِغِنَاءِ بُعَاثَ، فَاضْطَجَعَ عَلَى الْفِرَاشِ وَحَوَّلَ وَجْهَهُ، وَدَخَلَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ فَانْتَهَرَنِي وَقَالَ: مِزْمَارَةُ الشَّيْطَانِ عِنْدَ رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ؟ فَأَقْبَلَ عَلَيْهِ رَسُولُ الله عَلَيْهِ السَّلَامُ فَقَالَ: "دَعْهُمَا"، فَلَمَّا غَفَلَ غَمَزْتُهُمَا فَخَرَجَتَا. وَكَانَ يَوْمَ عِيدٍ يَلْعَبُ السُّودَانُ بِالدَّرَقِ وَالْحِرَابِ، فَإِمَّا سَأَلْتُ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ وَإِمَّا قَالَ: "تَشْتَهِينَ تَنْظُرِينَ". فَقُلْتُ: نَعَمْ، فَأَقَامَنِي وَرَاءَهُ، خَدِّي عَلَى خَدِّهِ، وَهُوَ يَقُولُ: "دُونَكُمْ يَا بَنِي أَرْفِدَةَ" حَتَّى إِذَا مَلِلْتُ قَالَ: "حَسْبُكِ". قُلْتُ: نَعَمْ، قَالَ: "فَاذْهَبِي". وَفِي رِوَايَةٍ: قَالَ: "دَعْهُنَّ، فَإِنَّ لِكُلِّ قَوْمٍ عِيدًا". (ق, ن)', 'ആഇശ(റ): ബുആസിനെപ്പറ്റിയുള്ള ഗാനമാലപിച്ചുകൊണ്ട് രണ്ട് പെൺകുട്ടികൾ എന്റടുത്തു നിൽക്കുമ്പോൾ നബി(സ) കടന്നുവന്നു. നബി(സ) മുഖം തിരിച്ച് വിരിപ്പിൽ കിടന്നു. അപ്പോൾ അബൂബക്കർ(റ) കടന്നുവരികയും എന്നെ വഴക്കു പറയുകയും ചെയ്തു. അദ്ദേഹം പറഞ്ഞു: പിശാചിന്റെ കുഴലൂത്ത് നബി(സ)യുടെ അടുത്ത് വെച്ചോ? നബി(സ) അദ്ദേഹത്തിനു നേരെ തിരിഞ്ഞ് പറഞ്ഞു: "അവരെ വിട്ടേക്കൂ." നബി(സ) ശ്രദ്ധിക്കാതിരുന്നപ്പോൾ ആഇശ(റ) ആ രണ്ടു പെൺകുട്ടികളേയും തോണ്ടി. അവർ പുറത്തുപോയി. പെരുന്നാൾ ദിവസം സുഡാനികൾ കുന്തവും, പരിചയും ഉപയോഗിച്ച് കളിക്കാറുണ്ട്. ഞാൻ നബി(സ)യോടു ചോദിക്കുകയോ അവിടുന്ന് (എന്നോട്) പറയുകയോ ചെയ്തു: "കളി കാണാൻ ഇഷ്ടമുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) തന്റെ പിന്നിൽ എന്നെ പിടിച്ചു നിർത്തി. എന്റെ കവിൾ അവിടുത്തെ കവിളിൽ തട്ടിയിരുന്നു. തിരുമേനി(സ) പറയുന്നുണ്ടായിരുന്നു: "ഹേ! ബനു അർഫിദക്കാരെ³ നിങ്ങൾ തുടരൂ." ഞാൻ കണ്ടുമടുത്തപ്പോൾ നബി(സ) ചോദിച്ചു: "മതിയോ?" ഞാൻ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "എന്നാൽ പൊയ്ക്കോളൂ."⁴ ഒരു റിപ്പോർട്ടിൽ: നബി(സ) പറഞ്ഞു: "അവരെ വിട്ടേക്കൂ, ഒരോ ജനതയ്ക്കും പെരുന്നാൾ (ആഘോഷം) ഉണ്ട്." (ബു,മു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', '³ എത്യോപ്യക്കാർക്ക് പറയുന്ന മറ്റൊരു പേര്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=51), 1, 'وَفِي رِوَايَةٍ: قَالَ: "دَعْهُنَّ، فَإِنَّ لِكُلِّ قَوْمٍ عِيدًا". (ق, ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أَبَا بَكْرِ الصِّدِّيقَ رَضِيَ اللهُ عَنْهُ دَخَلَ عَلَيْهَا وَعِنْدَهَا جَارِيَتَانِ تَضْرِبَانِ بِالدُّفِّ وَتُغَنِّيَانِ، وَرَسُولُ الله صَلَّى الله عَلَيْهِ وَسَلَّمَ مُسَجًّى بِثَوْبِهِ، وَفِي رِوَايَةٍ: مُتَسَجِّ ثَوْبَهُ، فَكَشَفَ عَنْ وَجْهِهِ فَقَالَ: "دَعْهُمَا يَا أَبَا بَكْرٍ، إِنَّهَا أَيَّامُ عِيدٍ". وَهُنَّ أَيَّامُ مِنًى، وَرَسُولُ الله صَلَّى الله عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ بِالْمَدِينَةِ. (ن)', 'ആഇശ(റ): രണ്ടു പെൺകുട്ടികൾ അവരുടെയടുത്ത് ദഫ്ഫ് മുട്ടി പാട്ടു പാടികൊണ്ടിരിക്കുമ്പോൾ അബൂബക്കർ(റ) കടന്നുവന്നു. നബി(സ) പുതച്ചു മൂടിയിരിക്കുകയായിരുന്നു. അപ്പോൾ നബി(സ) മുഖത്തുനിന്ന് തുണി മാറ്റികൊണ്ട് പറഞ്ഞു: "അബൂബക്കർ, അവരെ വിട്ടേക്കൂ (അവർ പാടട്ടെ), ഇത് ആഘോഷ ദിനമാണല്ലോ." അവ മിനാ ദിവസങ്ങൾ ആയിരുന്നു. അന്ന് നബി(സ) മദീനയിലായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 676, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=52), 1, 'وَفِي رِوَايَةٍ: مُتَسَجِّ ثَوْبَهُ، فَكَشَفَ عَنْ وَجْهِهِ فَقَالَ: "دَعْهُمَا يَا أَبَا بَكْرٍ، إِنَّهَا أَيَّامُ عِيدٍ". وَهُنَّ أَيَّامُ مِنًى، وَرَسُولُ الله صَلَّى الله عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ بِالْمَدِينَةِ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عِيَاضٍ الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ شَهِدَ عِيدًا بِالْأَنْبَارِ فَقَالَ: مَا لِي لَا أَرَاكُمْ تُقَلِّسُونَ كَمَا كَانَ يُقَلَّسُ عِنْدَ رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ. (جه)', 'ഇയാളുൽ അശ്അരി(റ): അദ്ദേഹം അമ്പാറിൽ ഒരു പെരുന്നാളിന് പങ്കെടുത്തു. അദ്ദേഹം ചോദിച്ചു: എന്തുകൊണ്ടാണ് നബി(സ)യുടെ അടുക്കൽ ദഫ്ഫു മുട്ടിയിരുന്നതുപോലെ നിങ്ങൾ ദഫ്ഫു മുട്ടാത്തത്? (ജ)', 'عِيَاضٍ الْأَشْعَرِيِّ', 'ഇയാളുൽ അശ്അരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 676, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ قَيْسِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا كَانَ شَيْءٌ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ إِلَّا وَقَدْ رَأَيْتُهُ إِلَّا شَيْءٌ وَاحِدٌ. فَإِنَّ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ كَانَ يُقَلَّسُ لَهُ يَوْمَ الْفِطْرِ. (جه)', 'ഖൈസുബ്നു സഅ്ദ്(റ): നബി(സ)യുടെ കാലത്തുണ്ടായിരുന്നതിൽ നിന്ന് ഒന്നല്ലാത്തതെല്ലാം ഞാൻ കണ്ടിട്ടുണ്ട്; നബി(സ)ക്ക് ചെറിയ പെരുന്നാൾ ദിവസം ദഫ്ഫു മുട്ടിക്കൊടുക്കാറുണ്ടായിരുന്നു (എന്നതാണത്). (ജ)', 'قَيْسِ بْنِ سَعْدٍ', 'ഖൈസുബ്നു സഅ്ദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَاءَ السُّودَانُ يَلْعَبُونَ بَيْنَ يَدَيِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ فِي يَوْمِ عِيدٍ، فَدَعَانِي، فَكُنْتُ أَطَّلِعُ إِلَيْهِمْ مِنْ فَوْقِ عَاتِقِهِ، فَمَا زِلْتُ أَنْظُرُ إِلَيْهِمْ حَتَّى كُنْتُ أَنَا الَّتِي انْصَرَفْتُ. (ن)', 'ആഇശ(റ): ഒരു പെരുന്നാൾ ദിവസം കളിച്ചുകൊണ്ട് ചില സുഡാൻ നിവാസികൾ നബി(സ)യുടെ സന്നിധിയിൽ എത്തി. അപ്പോൾ നബി(സ) എന്നെ വിളിച്ചു. നബി(സ)യുടെ ചുമലിനു മുകളിലൂടെ (അവരുടെ കളി) അവരെ ഞാൻ നോക്കിക്കൊണ്ടിരുന്നു. (കണ്ടു മടുത്ത്) ഞാനാണ് മടങ്ങിയത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: رَأَيْتُ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يَسْتُرُنِي بِرِدَائِهِ وَأَنَا أَنْظُرُ إِلَى الْحَبَشَةِ يَلْعَبُونَ فِي الْمَسْجِدِ، حَتَّى أَكُونَ أَنَا أَسْأَمُ، فَاقْدُرُوا قَدْرَ الْجَارِيَةِ الْحَدِيثَةِ السِّنِّ، الْحَرِيصَةِ عَلَى اللَّهْوِ. (ن)', 'ആഇശ(റ): പള്ളിയിൽ കളിക്കുന്ന അബ്സീനിയക്കാരുടെ കളി ഞാൻ കണ്ടുകൊണ്ടിരുന്നപ്പോൾ നബി(സ) എന്നെ അവിടുത്തെ മേൽ തട്ടം കൊണ്ട് മറച്ചിരുന്നു; ഞാൻ മതിയാക്കും വരെ. ചെറുപ്രായത്തിലുള്ള വിനോദ തത്പരയായ ഒരു പെൺകുട്ടിയുടെ സ്ഥിതി നിങ്ങൾ കണക്കിലെടുക്കുക. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ عُمَرُ وَالْحَبَشَةُ يَلْعَبُونَ فِي الْمَسْجِدِ، فَزَجَرَهُمْ عُمَرُ رَضِيَ اللهُ عَنْهُ، فَقَالَ رَسُولُ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "دَعْهُمْ يَا عُمَرُ، فَإِنَّمَا هُمْ بَنُو أَرْفِدَةَ". (خ,ن)', 'അബൂഹുറൈറ(റ): അബ്സീനിയക്കാരായ ചിലർ പള്ളിയിൽ വെച്ച് കളിച്ചു കൊണ്ടിരിക്കെ ഉമർ(റ) അവിടെ ചെന്ന് അവരെ ശാസിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഉമറേ, അവരെ വിട്ടേക്കുക. (അവർ കളിക്കട്ടെ) അവർ ബനൂ അർഫിദക്കാരാണ്." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى الله عَلَيْهِ وَسَلَّمَ قَالَ: "مَا الْعَمَلُ فِي أَيَّامٍ أَفْضَلَ مِنْهَا فِي هَذَا الْعَشْرِ؟" قَالُوا: وَلَا الْجِهَادُ؟ قَالَ: "وَلَا الْجِهَادُ، إِلَّا رَجُلٌ خَرَجَ يُخَاطِرُ بِنَفْسِهِ وَمَالِهِ، فَلَمْ يَرْجِعْ بِشَيْءٍ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) ചോദിച്ചു: "ഈ പത്തു ദിവസങ്ങളിൽ ചെയ്യുന്ന പ്രവർത്തനങ്ങളേക്കാൾ മഹത്വപൂർണ്ണമായ സൽകർമ്മം വേറെയില്ല." അവർ (സ്വഹാബികൾ) പറഞ്ഞു: ജിഹാദുമില്ലേ? തിരുമേനി(സ) പ്രതിവചിച്ചു: "ജിഹാദുമില്ല. പക്ഷെ, ജിഹാദിനായി തന്റെ ജീവനേയും, സമ്പത്തിനേയും അവഗണിച്ചു കൊണ്ട് ഇറങ്ങിത്തിരിക്കുയും, ഒന്നും നേടാതെ മടങ്ങിയെത്തുകയും ചെയ്യുന്ന ഒരാളുടെ ജിഹാദൊഴികെ." (ബു)', 'ابْنِ عَبَّاسٍ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 677, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ سُئِلَ عَنِ التَّلْبِيَةِ كَيْفَ كُنْتُمْ تَصْنَعُونَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: كَانَ يُلَبِّي الْمُلَبِّي لَا يُنْكَرُ عَلَيْهِ، وَيُكَبِّرُ الْمُكَبِّرُ فَلَا يُنْكَرُ عَلَيْهِ. (خ)', 'അനസുബ്ന് മാലിക്(റ): നബി(സ)യോടൊപ്പം നിങ്ങൾ എപ്രകാരമായിരുന്നു തൽബിയത് ചൊല്ലിയിരുന്നത് എന്ന് അദ്ദേഹത്തോട് ചോദിക്കുകയുണ്ടായി. അദ്ദേഹം പറഞ്ഞു: ഒരാൾ തൽബിയത് ചൊല്ലും. ആരും അത് എതിർക്കുകയില്ല. ഒരാൾ തക്ബീർ ചൊല്ലും. അതും ആരും എതിർക്കുകയില്ല. (തൽബിയത് ചൊല്ലുന്നവൻ അത് ചൊല്ലും. തക്ബീർ പറയുന്നയാൾ അത് പറയും) (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്ന് മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 678, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ فِطْرٍ، فَصَلَّى رَكْعَتَيْنِ لَمْ يُصَلِّ قَبْلَهُمَا وَلَا بَعْدَهُمَا، ثُمَّ أَتَى النِّسَاءَ وَمَعَهُ بِلَالٌ، فَأَمَرَهُنَّ بِالصَّدَقَةِ. فَجَعَلَتِ الْمَرْأَةُ تُلْقِي خُرْصَهَا وَسَخَابَهَا. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ചെറിയ പെരുന്നാൾ ദിവസം രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. അതിന് മുമ്പോ ശേഷമോ നിസ്കരിച്ചില്ല. പിന്നെ സ്ത്രീകളുടെ അടുത്തു ചെന്നു. നബി(സ)യോടൊപ്പം ബിലാലു(റ)മുണ്ടായിരുന്നു. അവരെ സ്വദഖ നൽകാൻ ഉപദേശിച്ചു. സ്ത്രീകൾ അതിൽ മോതിരങ്ങളും മറ്റു ആഭരണങ്ങളും ഇടുന്നുണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 678, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ فَصَلَّى بِهِمُ الْعِيدَ، لَمْ يُصَلِّ قَبْلَهَا وَلَا بَعْدَهَا. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) സ്വഹാബികളെയുമായി പെരുന്നാൾ നിസ്കരിച്ചു. അതിന് മുമ്പോ ശേഷമോ നിസ്കരിച്ചില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 678, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُصَلِّي قَبْلَ الْعِيدِ شَيْئًا، فَإِذَا رَجَعَ إِلَى مَنْزِلِهِ صَلَّى رَكْعَتَيْنِ. (جه)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നബി(സ) പെരുന്നാൾ നിസ്കാരത്തിനു മുമ്പ് നിസ്കരിച്ചിരുന്നില്ല. നിസ്കാര ശേഷം വീട്ടിലേക്ക് മടങ്ങിയാൽ അവിടെ വെച്ച് രണ്ട് റക്അത്ത് നിസ്കരിച്ചിരുന്നു. (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 678, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ رَضِيَ اللَّهُ عَنْهُ صَاحِبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَرَجَ مَعَ النَّاسِ فِي يَوْمِ عِيدِ فِطْرٍ أَوْ أَضْحَى، فَأَنْكَرَ إِبْطَاءَ الْإِمَامِ فَقَالَ: إِنَّا كُنَّا قَدْ فَرَغْنَا سَاعَتَنَا هَذِهِ , وَذَلِكَ حِينَ التَّسْبِيحِ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ): അദ്ദേഹം (നബി(സ)യുടെ സഹാബികളിൽപ്പെട്ടയാളായിരുന്നു) ജനങ്ങളോടൊപ്പം ചെറിയ പെരുന്നാളിനോ, അതോ ബലിപെരുന്നാളിനോ പുറപ്പെട്ടു. ഇമാം വൈകി വന്നതിൽ അദ്ദേഹം എതിർപ്പ് പ്രകടിപ്പിച്ചു. ശേഷം പറഞ്ഞു: ഞങ്ങൾ ഈ സമയത്ത് നിസ്കാരം കഴിഞ്ഞിരിക്കും. ളുഹാ നിസ്കാരമായിരുന്നു അത്. (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ بُسْرٍ', 'അബ്ദുല്ലാഹിബ്നു ബുസ്ർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 678, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ بَرَاءٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ نُوولَ يَوْمَ الْعِيدِ قَوْسًا فَخَطَبَ عَلَيْهِ. (د)', 'ബറാഅ്(റ): നബി(സ)ക്ക് പെരുന്നാൾ ദിവസം ഒരു വില്ല് നൽകപ്പെട്ടു. അങ്ങനെ അതിന്മേൽ പിടിച്ച് ഖുത്വുബ നിർവ്വഹിച്ചു. (ദ)', 'بَرَاءٍ', 'ബറാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ سَعْدِ بْنِ عَائِدٍ رَضِيَ اللهُ عَنْهُ - مُؤَذِّنِ رَسُولِ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ كَانَ يُكَبِّرُ فِي الْعِيدَيْنِ فِي الْأُولَى سَبْعًا قَبْلَ الْقِرَاءَةِ، وَفِي الْآخِرَةِ خَمْسًا قَبْلَ الْقِرَاءَةِ. (جه)', 'നബി(സ)യുടെ ബാങ്കു വിളിക്കാരനായ സഅ്ദുബ്നു ആഇദ്(റ): നബി(സ) രണ്ട് പെരുന്നാൾ നിസ്കാരങ്ങളിൽ ആദ്യത്തെ റക്അത്തിൽ ഖിറാഅത്തിനു മുൻപ് ഏഴ് തക്ബീറും, രണ്ടാം റക്അത്തിൽ ഖിറാഅത്തിനു മുൻപ് അഞ്ച് തക്ബീറും ചൊല്ലിയിരുന്നു. (ജ)', 'سَعْدِ بْنِ عَائِدٍ', 'നബി(സ)യുടെ ബാങ്കു വിളിക്കാരനായ സഅ്ദുബ്നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ كَانَ يُكَبِّرُ فِي الْفِطْرِ وَالْأَضْحَى فِي الْأُولَى سَبْعَ تَكْبِيرَاتٍ، وَفِي الثَّانِيَةِ خَمْسًا. قَالَ ابْنُ شِهَابٍ: سِوَى تَكْبِيرَتَيِ الرُّكُوعِ. (د,جه)', 'ആഇശ(റ): നബി(സ) ചെറിയ പെരുന്നാളിലും ബലിപെരുന്നാളിലും ഒന്നാം റക്അത്തിൽ ഏഴും, രണ്ടാമത്തേതിൽ അഞ്ചും തക്ബീറുകൾ ചൊല്ലിയിരുന്നു. ഇബ്നുശിഹാബ് പറഞ്ഞു: റുകൂഇന്റെ രണ്ട് തക്ബീറുകൾ കൂടാതെയാണിത്. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ نَبِيُّ اللهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ: "التَّكْبِيرُ فِي الْفِطْرِ سَبْعٌ فِي الْأُولَى، وَخَمْسٌ فِي الْآخِرَةِ، وَالْقِرَاءَةُ بَعْدَهُمَا كِلْتَيْهِمَا". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ചെറിയ പെരുന്നാളിലെ തക്ബീർ ഒന്നാമത്തെ റക്അത്തിൽ ഏഴും, രണ്ടാമത്തേതിൽ അഞ്ചും പ്രാവശ്യമാണ്. ഖിറാഅത്ത് അവ രണ്ടിനും ശേഷമാണ്." (ദ)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى الله عَلَيْهِ وَسَلَّمَ كَانَ يُكَبِّرُ فِي الْفِطْرِ الْأُولَى سَبْعًا، ثُمَّ يَقْرَأُ، ثُمَّ يُكَبِّرُ، ثُمَّ يَقُومُ فَيُكَبِّرُ أَرْبَعًا، [ وَفِي رِوَايَةٍ: خَمْسًا] ثُمَّ يَقْرَأُ، ثُمَّ يَرْكَعُ. (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) ചെറിയ പെരുന്നാളിൽ ഒന്നാമത്തെ റക്അത്തിൽ ഏഴു തക്ബീർ ചൊല്ലും. പിന്നെ ഖുർആൻ പാരായണം ചെയ്യും, തക്ബീർ ചൊല്ലും. പിന്നെ എഴുന്നേറ്റുനിന്ന് നാല് തക്ബീർ ചൊല്ലും, (ഒരു റിപ്പോർട്ടിൽ: അഞ്ച് തക്ബീർ എന്നാണ്) ശേഷം ഖുർആൻ പാരായണം ചെയ്യും, പിന്നെ റുകൂഅ് ചെയ്യും. (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], 'وَفِي رِوَايَةٍ: خَمْسًا', null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=26 and h.hadith_no=68), 1, 'وَفِي رِوَايَةٍ: خَمْسًا] ثُمَّ يَقْرَأُ، ثُمَّ يَرْكَعُ. (د,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ سَعِيدِ بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ أَبَا مُوسَى الْأَشْعَرِيَّ وَحُذَيْفَةَ بْنَ الْيَمَانِ كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى الله عَلَيْهِ وَسَلَّمَ يُكَبِّرُ فِي الْأَضْحَى وَالْفِطْرِ؟ فَقَالَ أَبُو مُوسَى: كَانَ يُكَبِّرُ أَرْبَعًا، تَكْبِيرَهُ عَلَى الْجَنَائِزِ. فَقَالَ حُذَيْفَةُ: صَدَقَ، فَقَالَ أَبُو مُوسَى: كَذَلِكَ كُنْتُ أُكَبِّرُ فِي الْبَصْرَةِ حَيْثُ كُنْتُ عَلَيْهِمْ. (د)', 'സഈദുബ്നുൽ ആസ്(റ): അദ്ദേഹം അബൂമൂസൽ അശ്അരി(റ)യോടും, ഹുദൈഫ(റ)യോടും ചോദിച്ചു: നബി(സ) ചെറിയ പെരുന്നാളിലും, ബലിപെരുന്നാളിലും എങ്ങനെയായിരുന്നു തക്ബീർ ചൊല്ലിയിരുന്നത്? അബൂമൂസ(റ) പറഞ്ഞു: മയ്യിത്ത് നിസ്കാരത്തിൽ തക്ബീർ ചൊല്ലിയപോലെ നാല് പ്രാവശ്യമായിരുന്നു തക്ബീർ ചൊല്ലിയിരുന്നത്. അപ്പോൾ ഹുദൈഫ(റ) പറഞ്ഞു: അദ്ദേഹം പറഞ്ഞത് സത്യമാണ്. അബൂമൂസ(റ) പറഞ്ഞു: ഞാൻ ബസ്വറയിലുണ്ടായിരുന്നപ്പോൾ ഞാനും അപ്രകാരമാണ് തക്ബീർ ചൊല്ലിയിരുന്നത്. (ദ)', 'سَعِيدِ بْنِ الْعَاصِ', 'സഈദുബ്നുൽ ആസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 679, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي عُمَيْرِ بْنِ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنْ عُمُومَةٍ لَهُ مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّ رَكْبًا جَاءُوا إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَشْهَدُونَ، أَنَّهُمْ رَأَوُا الْهِلَالَ بِالْأَمْسِ، فَأَمَرَهُمْ أَنْ يُفْطِرُوا، وَإِذَا أَصْبَحُوا أَنْ يَغْدُوا إِلَى مُصَلَّاهُمْ. (د،ن،جه)', 'അബൂഉമൈറുബ്നു അനസുബ്നു മാലിക്(റ): (അദ്ദേഹം സ്വഹാബികളായ തന്റെ പിതൃവ്യന്മാരിൽ നിന്നുദ്ധരിക്കുന്നു.) ഇന്നലെ ഞങ്ങൾ മാസപ്പിറവി കണ്ടുവെന്ന സാക്ഷ്യവുമായി ഒരു ഒട്ടക സംഘം നബി(സ)യുടെ അടുത്തു വന്നു. അപ്പോൾ നബി(സ) അവരോട് നോമ്പു മുറിക്കാൻ കൽപിച്ചു. നേരം പുലർന്നാൽ നേരത്തെ അവരുടെ നിസ്കാര സ്ഥലത്തേക്ക് പുറപ്പെടാനും കൽപിച്ചു. (ദ,ന,ജ)', 'أَبِي عُمَيْرِ بْنِ أَنَسٍ', 'അബൂഉമൈറുബ്നു അനസുബ്നു മാലിക്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ بَكْرِ بْنِ مُبَشِّرٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ أَغْدُو مَعَ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمُصَلَّى يَوْمَ الْفِطْرِ وَيَوْمَ الْأَضْحَى، فَنَسْلُكُ بَطْنَ بَطْحَانَ حَتَّى نَأْتِيَ الْمُصَلَّى. فَنُصَلِّي مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ نَرْجِعُ مِنْ بَطْنِ بَطْحَانَ إِلَى بُيُوتِنَا. (د)', 'ബക്‌റുബ്നു മുബശ്ശിർ(റ): ഞാൻ നബി(സ)യുടെ അനുചരരോടൊപ്പം നിസ്കാര സ്ഥലത്തേക്ക് ബലിപെരുന്നാളിനും ചെറിയ പെരുന്നാളിനും നേരത്തെ പോയിരുന്നു. ഞങ്ങൾ ബത്‌ഹാൻ മലഞ്ചെരുവിലൂടെ പോയി നിസ്കാര സ്ഥലത്തെത്തും. നബി(സ)യോടൊപ്പം നിസ്കരിച്ച് ബത്‌ഹാൻ മലഞ്ചെരുവിലൂടെ തന്നെ വീട്ടിലേക്കു മടങ്ങും. (ദ)', 'بَكْرِ بْنِ مُبَشِّرٍ الْأَنْصَارِيِّ', 'ബക്‌റുബ്നു മുബശ്ശിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَصَابَهُمْ مَطَرٌ فِي يَوْمِ عِيدٍ، فَصَلَّى بِهِمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْعِيدِ فِي الْمَسْجِدِ. (د،جه)', 'അബൂഹുറൈറ(റ): മഴയുള്ള ഒരു പെരുന്നാൾ ദിവസം നബി(സ) അവരെയുമായി പള്ളിയിൽ വെച്ച് പെരുന്നാൾ നിസ്കരിച്ചു. (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ سَعْدِ بْنِ عَائِدٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَخْرُجُ إِلَى الْعِيدِ مَاشِيًا وَيَرْجِعُ مَاشِيًا. [فيه راو ضعيف] (جه)', 'സഅ്ദുബ്നു ആഇദ്(റ): നബി(സ) പെരുന്നാൾ നിസ്കാരത്തിന് നടന്നു പോവുകയും നടന്നു തന്നെ മടങ്ങുകയും ചെയ്തിരുന്നു. (ഇതിൽ ദുർബ്ബല റിപ്പോർട്ടറുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'سَعْدِ بْنِ عَائِدٍ', 'സഅ്ദുബ്നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'فيه راو ضعيف', 'ഇതിൽ ദുർബ്ബല റിപ്പോർട്ടറുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: مِنَ السُّنَّةِ أَنْ تَخْرُجَ إِلَى الْعِيدِ مَاشِيًا. وَأَنْ تَأْكُلَ شَيْئًا قَبْلَ أَنْ تَخْرُجَ. (ت،جه)', 'അലി(റ): പെരുന്നാൾ ദിവസം നിസ്കാരത്തിനായി നടക്കലും പുറപ്പെടും മുമ്പ് എന്തെങ്കിലും ഭക്ഷിക്കലും സുന്നത്തിൽ പെട്ടതാണ്. (തു,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 680, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ سَعْدِ بْنِ عَائِدٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ إِلَى الْعِيدَيْنِ سَلَكَ عَلَى دَارِ سَعِيدِ بْنِ أَبِي الْعَاصِ، ثُمَّ عَلَى أَصْحَابِ الْفَسَاطِيطِ، ثُمَّ انْصَرَفَ فِي الطَّرِيقِ الْأُخْرَى طَرِيقِ بَنِي زُرَيْقٍ. ثُمَّ يَخْرُجُ عَلَى دَارِ عَمَّارِ بْنِ يَاسِرٍ، وَدَارِ أَبِي هُرَيْرَةَ إِلَى الْبَلَاطِ. [إسناده ضعيف] (جه)', 'സഅ്ദുബ്നു ആഇദ്(റ): നബി(സ) രണ്ട് പെരുന്നാൾ നിസ്കാരങ്ങൾക്കു പുറപ്പെടുമ്പോൾ സഈദുബ്നു അബിൽ ആസ്വിന്റെ വീടിന്റെയും, കുടിലിൽ താമസിക്കുന്നവരുടെയും അടുത്തുകൂടെ പോവും. മടങ്ങി വരുമ്പോൾ ബനൂസുറൈഖിന്റെ വഴിയിലൂടെ പോയി അമ്മാറുബ്നു യാസിറി(റ)ന്റെയും അബൂഹുറൈറ(റ)യുടെയും വീടിനരികിലൂടെ ബലാത്വി(മദീനയിലെ ഒരു സ്ഥലം)ലേക്കു പോകും. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'سَعْدِ بْنِ عَائِدٍ', 'സഅ്ദുബ്നു ആഇദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ يَخْرُجُ إِلَى الْعِيدِ فِي طَرِيقٍ وَيَرْجِعُ فِي أُخْرَى. وَيَزْعُمُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُ ذَلِكَ. (د,جه)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം പെരുന്നാൾ നിസ്കാരത്തിന് ഒരു വഴിയിലൂടെ പുറപ്പെടുകയും, മറ്റൊരു വഴിക്ക് മടങ്ങുകയും ചെയ്യാറുണ്ടായിരുന്നു. നബി(സ) ഇപ്രകാരം ചെയ്തിരുന്നതായി പറയുന്നു. (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْتِي الْعِيدَ مَاشِيًا، وَيَرْجِعُ فِي غَيْرِ الطَّرِيقِ الَّذِي ابْتَدَأَ فِيهِ. (جه)', 'അബൂറാഫിഅ്(റ): നബി(സ) പെരുന്നാൾ നിസ്കാരത്തിന് നടന്നുവരാറുണ്ടായിരുന്നു. ശേഷം പുറപ്പെട്ടതല്ലാത്ത ഒരു വഴിയിലൂടെ മടങ്ങുകയും ചെയ്തിരുന്നു. (ജ)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَأَلَ رَجُلًا: هَلْ شَهِدْتَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِيدَيْنِ فِي يَوْمٍ؟ قَالَ: نَعَمْ، قَالَ: فَكَيْفَ كَانَ يَصْنَعُ؟ قَالَ: صَلَّى الْعِيدَ، ثُمَّ رَخَّصَ فِي الْجُمُعَةِ. ثُمَّ قَالَ: "مَنْ شَاءَ أَنْ يُصَلِّيَ فَلْيُصَلِّ". (د,ن,جه)', 'സൈദുബ്നു അർഖം(റ): അദ്ദേഹം ഒരാളോട് ചോദിച്ചു: താങ്കൾ നബി(സ)യോടൊപ്പം ഒരേ ദിവസം രണ്ട് പെരുന്നാളിൽ (വെള്ളിയാഴ്ചയും, പെരുന്നാളും) പങ്കെടുത്തിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ. സൈദുബ്നുഅർഖം(റ) ചോദിച്ചു: നബി(സ) എന്താണ് ചെയ്തിരുന്നത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ) പെരുന്നാൾ നിസ്കരിച്ചു, പിന്നെ ജുമുഅയിൽ ഇളവു നൽകി. ശേഷം പറഞ്ഞു: "നിസ്കരിക്കാൻ ഉദ്ദേശിക്കുന്നവർക്ക് നിസ്കരിക്കാം." (ദ,ന,ജ)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "اجْتَمَعَ عِيدَانِ فِي يَوْمِكُمْ هَذَا، فَمَنْ شَاءَ أَجْزَأَهُ مِنَ الْجُمُعَةِ، وَإِنَّا مُجَمِّعُونَ إِنْ شَاءَ اللَّهُ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കിന്ന് രണ്ട് പെരുന്നാളുകൾ ഒരുമിച്ചുകൂടിയിരിക്കുന്നു. ഉദ്ദേശിക്കുന്നവർക്ക് ജുമുഅക്ക് പകരം പെരുന്നാൾ നിസ്കാരം കൊണ്ട് മതിയാക്കാം. നാം ജുമുഅയും നിസ്കരിക്കുന്നുണ്ട്." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: اجْتَمَعَ عِيدَانِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِالنَّاسِ، ثُمَّ قَالَ: "مَنْ شَاءَ أَنْ يَأْتِيَ الْجُمُعَةَ فَلْيَأْتِهَا، وَمَنْ شَاءَ أَنْ يَتَخَلَّفَ فَلْيَتَخَلَّفْ". [في إسناده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ)യുടെ കാലത്ത് രണ്ട് പെരുന്നാളുകൾ ഒരുമിച്ചുവന്നു. നബി(സ) ജനങ്ങളുമായി നിസ്കരിച്ചു. ശേഷം പറഞ്ഞു: "ജുമുഅക്കു വരാൻ ഉദ്ദേശിക്കുന്നവർ വരട്ടെ, വരാതിരിക്കുന്നവർ വരാതിരിക്കട്ടെ." (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 681, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ وَهْبِ بْنِ كَيْسَانَ رَضِيَ اللهُ عَنْهُ قَالَ: اجْتَمَعَ عِيدَانِ عَلَى عَهْدِ ابْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا، فَأَخَّرَ الْخُرُوجَ حَتَّى تَعَالَى النَّهَارُ، ثُمَّ خَرَجَ فَخَطَبَ فَأَطَالَ الْخُطْبَةَ، ثُمَّ نَزَلَ فَصَلَّى، وَلَمْ يُصَلِّ لِلنَّاسِ يَوْمَئِذٍ الْجُمُعَةَ، فَذُكِرَ ذَلِكَ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فَقَالَ: أَصَابَ السُّنَّةَ. (ن)', 'വഹ്ബുബ്നു കൈസാൻ(റ): രണ്ടു പെരുന്നാൾ (ജുമുഅയും, പെരുന്നാളും) ഇബ്നുസുബൈർ(റ)ന്റെ കാലത്ത് ഒരേ ദിവസം വന്നു. പകൽ ഉയരുന്നതു വരെ നിസ്കരിക്കാൻ അദ്ദേഹം ഇറങ്ങിത്തിരിച്ചില്ല. പിന്നീട് നിസ്കരിക്കാൻ എത്തുകയും നീണ്ട ഒരു ഖുത്വുബ നിർവ്വഹിക്കുകയും ചെയ്തു. ഖുത്വുബ കഴിഞ്ഞ് നിസ്കരിച്ചു. അന്ന് ആളുകൾക്ക് ഇമാമായി ജുമുഅഃ നിസ്കരിച്ചില്ല. ഇബ്നുഅബ്ബാസി(റ)നോട് ഈ വിവരം പറയപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: അദ്ദേഹം അനുഷ്ഠിച്ചത് ശരിയായ ചര്യയാണ്. (ന)', 'وَهْبِ بْنِ كَيْسَانَ', 'വഹ്ബുബ്നു കൈസാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 682, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُلْبَسَ السِّلَاحُ فِي بِلَادِ الْإِسْلَامِ فِي الْعِيدَيْنِ، إِلَّا أَنْ يَكُونُوا بِحَضْرَةِ الْعَدُوِّ. [في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ശത്രുവിന്റെ സാന്നിധ്യത്തിലല്ലാതെ രണ്ട് പെരുന്നാൾ ദിവസങ്ങളിൽ ഇസ്ലാമിക രാഷ്ട്രങ്ങളിൽ ആയുധമേന്തുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 682, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَغْتَسِلُ يَوْمَ الْفِطْرِ وَيَوْمَ الْأَضْحَى. [في إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ചെറിയ പെരുന്നാളിനും ബലി പെരുന്നാളിനും കുളിക്കാറുണ്ടായിരുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 682, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنِ الْفَاكِهِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ: وَكَانَتْ لَهُ صُحْبَةٌ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ يَوْمَ الْفِطْرِ وَيَوْمَ النَّحْرِ وَيَوْمَ عَرَفَةَ. وَكَانَ الْفَاكِهُ يَأْمُرُ أَهْلَهُ بِالْغُسْلِ فِي هَذِهِ الْأَيَّامِ. [في إسناده ضعيف] (جه)', 'ഫാകിഹുബ്നു സഅ്ദ്(റ) (നബി(സ)യുടെ സ്വഹാബി): നബി(സ) ചെറിയ പെരുന്നാളിനും ബലിപെരുന്നാളിനും അറഫാ ദിനത്തിലും കുളിക്കാറുണ്ടായിരുന്നു. ഈ ദിനങ്ങളിൽ കുളിക്കാൻ ഫാകിഹ്(റ) തന്റെ കുടുംബത്തോട് കൽപിച്ചിരുന്നു. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'الْفَاكِهِ بْنِ سَعْدٍ', 'ഫാകിഹുബ്നു സഅ്ദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 682, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=26 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
